(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c40"]=[{"id":"00011585","register_sub_id":"101","register_pk":"210514","name":"大川上美良布神社神庫","kana":"おおかわかみびらふじんじゃしんこ","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"高知県","address":"高知県香美市香北町韮生野大宮243-1","lat":33.65006389,"lng":133.78387389,"geo_status":"db","era":"天保12年（1841）／昭和61年改修","year":1841,"year_source":"db","year_min":1841,"year_max":1841,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積19㎡","structure_material":"土蔵造2階建","registered":"2017.05.02(平成29.05.02)","register_no":"39-0293","desc":"桁行三間梁間二間、庇付の二階建土蔵。切妻造平入、置屋根形式。二段に水切瓦を廻し、腰壁は四面で異なる土佐漆喰の鏝仕上げとする。随所に彫刻を嵌め込んで飾り、北妻の雲形の窓上部は天邪鬼が唐破風状の庇を支え、鬼と雲の鏝絵で飾り特徴ある外観を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011585"},{"id":"00004063","register_sub_id":"101","register_pk":"105053","name":"桑瀬神社本殿","kana":"くわぜじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県吾川郡いの町桑瀬","lat":33.78396614,"lng":133.30784897,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、板葺、建築面積6.2㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"39 － 0131","desc":"礫滝横の峻険な山肌を切り開いた６坪程の社地に建つ。ほぼ南面する鞘殿に収まる切妻造，板葺，平入の一間社で，背面と正面の前後に錣屋根を架け，正面左右柱上部や蟇股などに龍，獏，鳳凰などの彩色彫刻を施す。古くから地区住民により守られてきた神社。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004063"},{"id":"00003170","register_sub_id":"101","register_pk":"104160","name":"正覚寺石垣","kana":"しょうがくじいしがき","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"low","period":"昭和前","pref":"高知県","address":"高知県安芸郡奈半利町乙1718-1","lat":33.42408626,"lng":134.02196069,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"石造、延長31m","structure_material":"石造","registered":"2003.01.31(平成15.01.31)","register_no":"39 － 0074","desc":"境内地の南辺に位置し，中央東寄りに門を開く。「イシグロ」と呼ばれる台風時等海からの強風避けの石垣で，２０～３０ｃｍ程の比較的大きな玉石で高さ１．５ｍ厚１ｍの外塀を築造し，類例の少ない昭和初期寺院境内景観をつくりだしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003170"},{"id":"00003169","register_sub_id":"101","register_pk":"104159","name":"正覚寺本堂","kana":"しょうがくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"高知県","address":"高知県安芸郡奈半利町乙1718-1","lat":33.42422979,"lng":134.02215441,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積34㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"39 － 0073","desc":"国道から南に入った境内地の西辺近くに東面して建つ。桁行４間梁間４間規模，向拝付きの宝形造本堂で右瓦が使用されている。奥に新本堂が増築された以降も外陣的な役割を果たしており，四国三十三観音霊場第九番札所として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003169"},{"id":"00006342","register_sub_id":"101","register_pk":"107325","name":"乗光寺書院","kana":"じょうこうじしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県安芸郡安田町大字安田1877-3","lat":33.43903328,"lng":133.98210717,"geo_status":"db","era":"大正末期／昭和中期改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"木造平屋建、瓦葺、建築面積41㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"39 － 0231","desc":"敷地の中央に南北棟で建つ木造平屋建である。屋根は寄棟造桟瓦葺で、軒先を金属板葺とする。内部はトコと棚を構える数寄屋風の６畳座敷と次の間４畳からなり、東西に榑縁をつける。小規模ながら落ち着いた佇まいの建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006342"},{"id":"00006343","register_sub_id":"101","register_pk":"107326","name":"乗光寺門","kana":"じょうこうじもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"大正","pref":"高知県","address":"高知県安芸郡安田町大字安田1877-3","lat":33.43910301,"lng":133.98204095,"geo_status":"db","era":"大正末期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"鉄筋コンクリート造、間口3.0m、脇門付","structure_material":"鉄筋コンクリート造","registered":"2007.12.05(平成19.12.05)","register_no":"39 － 0232","desc":"敷地の西辺、北寄りに開く門で南に脇門がつく。主門は間口３．０ｍ、高さ３．０ｍのコンクリート造の方柱で、柱頭下部に歯飾りを施す。上部に鉄製の欠円アーチを渡して門灯を掲げる。脇門門柱は幅０．９ｍで主門と同じ意匠になる。近代における寺院表門の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006343"},{"id":"00009678","register_sub_id":"101","register_pk":"194674","name":"定福寺庫裏","kana":"じょうふくじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"高知県","address":"高知県長岡郡大豊町粟生字寺ノナル158-3","lat":33.79274912,"lng":133.76955788,"geo_status":"db","era":"江戸末期／明治18移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、銅板葺、建築面積241㎡","structure_material":"木造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"39 － 0276","desc":"本堂より一段低い位置に南面し、入母屋造銅板葺で背面に持仏堂を張出す。主体部は前後二列に一〇室を並べ、西寄りに入母屋造の玄関、西端列にトコを備えた表間を配し、南西面に縁を廻らせる。東側の旧土間に大黒柱を残すなど、当地の大型民家の名残を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009678"},{"id":"00009677","register_sub_id":"101","register_pk":"194673","name":"定福寺本堂","kana":"じょうふくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"高知県","address":"高知県長岡郡大豊町粟生字粟生山159-3","lat":33.79304655,"lng":133.7692081,"geo_status":"db","era":"安永8","year":1779,"year_source":"db","year_min":1779,"year_max":1779,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積145㎡","structure_material":"木造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"39 － 0275","desc":"山中に所在する境内の奥に南面する。桁行五間梁間五間、入母屋造銅板葺、正面向拝付。中央の方三間を格天井張の内陣とし、正面一間通を外陣、両側に脇陣、背面を後陣とする。各面の一部に桟唐戸を吊る他は横板張とし、閉鎖的な構えになる真言宗寺院本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009677"},{"id":"00004066","register_sub_id":"101","register_pk":"105056","name":"善法寺本堂","kana":"ぜんぽうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県吾川郡仁淀川町土居甲1023","lat":33.60947583,"lng":133.17431586,"geo_status":"db","era":"明治初期／明治32頃改造","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積122㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"39 － 0134","desc":"土居川と安居川の合流地近くの河岸上に位置する。池川郷庄屋宅の客殿を本堂に充てたと伝える。桁行５間梁間５間規模，入母屋造，桟瓦葺で，屋根の各面には左瓦を使用する。大きな入母屋の妻は対岸から見ることができ，地区の格好のランドマークとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004066"},{"id":"00003736","register_sub_id":"101","register_pk":"104726","name":"長法寺本堂","kana":"ちょうほうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"高知県","address":"高知県安芸郡田野町1894","lat":33.42868306,"lng":134.01001914,"geo_status":"db","era":"文政5","year":1822,"year_source":"db","year_min":1822,"year_max":1822,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積149㎡","structure_material":"木造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"39 － 0093","desc":"桁行５間半梁行６間規模を有し，正面に１間の向拝を延ばす。屋根は入母屋造，桟瓦葺，軒は一軒疎垂木，組物平三斗，中備蟇股で，正面１間通りと両側面半間分を入側とし，桁行４間半梁行２間半分を外陣に充てる。安芸地方における江戸後期真宗寺院本堂の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003736"},{"id":"00003737","register_sub_id":"101","register_pk":"104727","name":"長法寺門","kana":"ちょうほうじもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"高知県","address":"高知県安芸郡田野町1894","lat":33.42843903,"lng":134.01010504,"geo_status":"db","era":"慶応2","year":1866,"year_source":"db","year_min":1866,"year_max":1866,"year_label":null,"structure":"木造、瓦葺、間口2.8m、袖塀付","structure_material":"木造","registered":"2003.12.01(平成15.12.01)","register_no":"39 － 0094","desc":"本堂の南方に東西棟で建つ。切妻造，桟瓦葺，間口１間半規模の１間薬医門で，本柱に五平材を用い，棟を蟇股で受けている点に特徴がある。間口の割にややたちが高く感じられるが，両袖に１間長の瓦葺板塀を従えて安定感ある姿形をつくりだしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003737"},{"id":"00004189","register_sub_id":"101","register_pk":"105179","name":"仁井田神社鞘殿","kana":"にいだじんじゃさやでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"大正","pref":"高知県","address":"高知県高知市土佐山桑尾字大潰78番イ","lat":33.63657099,"lng":133.52047508,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積25㎡","structure_material":"木造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"39 － 0154","desc":"拝殿奥にある本殿を保護する施設。桁行４．５ｍ，梁間５．６ｍ，切妻造，平入で，銅板葺の屋根はもと茅葺である。側廻りは角柱を立て，柱間は貫と角材を格子状に組んで厳重に囲う。質素なつくりであるが，拝殿と釣り合った規模を有し，社頭景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004189"},{"id":"00004188","register_sub_id":"101","register_pk":"105178","name":"仁井田神社拝殿","kana":"にいだじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県高知市土佐山桑尾字大潰78番イ","lat":33.63654824,"lng":133.52049545,"geo_status":"db","era":"明治22","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積57㎡","structure_material":"木造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"39 － 0153","desc":"桁行９．８ｍ，梁間５．８ｍ，入母屋造，妻入で，桟瓦葺屋根は左瓦を用いる。側廻りに角柱を立てて桁を受け，柱間に中敷居を入れて格子を建て込み，軒の出桁は渦紋付の持送板で受ける。簡素な形式であるが，社頭景観の構成上，欠かせない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004188"},{"id":"00004187","register_sub_id":"101","register_pk":"105177","name":"仁井田神社本殿","kana":"にいだじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県高知市土佐山桑尾字大潰78番イ","lat":33.63657665,"lng":133.52046918,"geo_status":"db","era":"明治22","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"木造平屋建、板葺、建築面積3.6㎡","structure_material":"木造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"39 － 0152","desc":"覆屋内にある桁行１．４ｍの１間社流造で，正側面に高欄付の切目縁を廻し，正面には浜縁をつける。身舎は円柱上に台輪を廻し，拳鼻付の出組を詰組にする。庇の龍，脇障子の松だけでなく中備に花鳥や山など，多彩な彫物を要所に配して，華やかな構成とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004187"},{"id":"00004186","register_sub_id":"101","register_pk":"105176","name":"春宮神社拝殿","kana":"はるみやじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県高知市土佐山桑尾字横平629番イ","lat":33.63742148,"lng":133.50860572,"geo_status":"db","era":"明治11","year":1878,"year_source":"db","year_min":1878,"year_max":1878,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積35㎡","structure_material":"木造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"39 － 0151","desc":"入母屋造，桟瓦葺，妻入，正面１間向拝付で，長方形平面は後半中央に本殿を安置し，前半を拝殿とする。軸部は角柱を立て，前半のみ大斗・舟肘木で丸桁をうける。小壁に配した龍や，波涛に兎・平目・鯉など躍動感のある彫物が，当時の造形の傾向を示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004186"},{"id":"00004185","register_sub_id":"101","register_pk":"105175","name":"春宮神社本殿","kana":"はるみやじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"高知県","address":"高知県高知市土佐山桑尾字横平629番イ","lat":33.63743942,"lng":133.5085551,"geo_status":"db","era":"文政7","year":1824,"year_source":"db","year_min":1824,"year_max":1824,"year_label":null,"structure":"木造平屋建、板葺、建築面積3.9㎡","structure_material":"木造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"39 － 0150","desc":"江戸前期の創建と伝える神社。覆屋を兼ねた拝殿奥にある１間社春日造で，建築年代は銘札より判明する。身舎は木製土台上に円柱を立てて三斗を組み，屋根はこけら葺，軒は吹寄垂木とする。彩色がほとんどない素木造で，装飾も庇の象鼻や蟇股程度と簡明な意匠。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004185"},{"id":"00006725","register_sub_id":"101","register_pk":"107708","name":"安田八幡宮玉垣","kana":"やすだはちまんぐうたまがき","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"low","period":"江戸","pref":"高知県","address":"高知県安芸郡安田町大字安田2170","lat":33.43812681,"lng":133.98061727,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"石造、延長19m","structure_material":"石造","registered":"2007.12.05(平成19.12.05)","register_no":"39 － 0235","desc":"神社参道の両脇に設けられた石造玉垣。間口４．６ｍ、長さ１６ｍ、高さ０．６ｍで、親柱を９間に立て、各間小柱５本で笠石を受ける。上手の石段部分は長さ３．０ｍで、両端に親柱、中間に中柱を置き、小石柱５本で笠石を受ける。参道景観を整える施設である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006725"},{"id":"00016455","register_sub_id":"101","register_pk":"536522","name":"宇美八幡宮神門","kana":"うみはちまんぐうしんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和中","pref":"福岡県","address":"福岡県糟屋郡宇美町宇美一丁目4104-1","lat":33.57023333,"lng":130.50861667,"geo_status":"db","era":"昭和33年","year":1958,"year_source":"db","year_min":1958,"year_max":1958,"year_label":null,"structure":"木造、銅板葺、間口7.9m","structure_material":"木造","registered":"2025.11.17(令和7.11.17)","register_no":"40 - 0258","desc":"東西に延びる参道中央部に位置する八脚門。基壇上に西面して建つ切妻造銅板葺で、円柱の主柱で棟木を支え、角柱の控柱と飛貫、頭貫で固める。柱間は全て吹放ち、上部は化粧軒裏を現す。軒反り優美で、参道を見通す開放的なつくりが境内の軸線を強調する神門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016455"},{"id":"00016454","register_sub_id":"101","register_pk":"536521","name":"宇美八幡宮拝殿及び幣殿","kana":"うみはちまんぐうはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県糟屋郡宇美町宇美一丁目4104","lat":33.57035833,"lng":130.50881667,"geo_status":"db","era":"明治19年／明治32年・昭和33年増築","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積100㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"40 - 0257","desc":"本殿の前面に位置する拝殿及び弊殿。拝殿は西面して建つ切妻造妻入銅板葺で、正面に増築の軒唐破風付きの入母屋造向拝を設け、周囲に庇を廻らす。後方に両下造銅板葺の幣殿を接続する。増築による変化ある屋根構成が優美で、境内中核部の景観を形成する社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016454"},{"id":"00016453","register_sub_id":"101","register_pk":"536520","name":"宇美八幡宮本殿","kana":"うみはちまんぐうほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県糟屋郡宇美町宇美一丁目4104","lat":33.57043611,"lng":130.50898056,"geo_status":"db","era":"明治19年","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積62㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"40 - 0256","desc":"市街地の中心部に位置する神社の本殿。境内東側に西面して建つ桁行五間梁間三間、入母屋造檜皮葺で一間向拝を付し、周囲に刎高欄付縁を廻らし脇障子を建てる。組物は出組、軒は二軒繁垂木。向拝の獅子鼻、籠彫の手挟など精緻な彫刻で飾った華麗な大規模社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016453"},{"id":"00014978","register_sub_id":"101","register_pk":"519238","name":"観世音寺宝蔵","kana":"かんぜおんじほうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和中","pref":"福岡県","address":"福岡県太宰府市観世音寺五丁目51-3","lat":33.51493611,"lng":130.52227222,"geo_status":"db","era":"昭和34年／昭和36年・平成21年改修","year":1959,"year_source":"db","year_min":1959,"year_max":1959,"year_label":null,"structure":"鉄筋コンクリート造2階建、瓦葺、建築面積340㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"40 - 0224","desc":"大宰府政庁跡に近い観世音寺境内に建つ文化財収蔵展示施設。防湿・防熱効果を高めるためピロティと二重壁を採用した鉄筋コンクリート造建築。梁にハンチを付けず、二軒風の深い軒を舟肘木で支え、腰壁は精緻な瓦積で仕上げる。端正かつ優美な戦後の和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014978"},{"id":"00013466","register_sub_id":"101","register_pk":"368562","name":"教圓寺鐘楼","kana":"きょうえんじしょうろう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"福岡県","address":"福岡県豊前市大字宇島215","lat":33.62244444,"lng":131.14098611,"geo_status":"db","era":"文久3年(1863)／昭和55年改修","year":1863,"year_source":"db","year_min":1863,"year_max":1863,"year_label":null,"structure":"木造3階建、瓦葺、建築面積41㎡","structure_material":"木造3階建","registered":"2020.08.17(令和2.08.17)","register_no":"40 － 0173","desc":"周防灘に面する宇島に位置し、旧中津街道沿いの境内南西隅に建つ。正面三間、側面二間、三階建袴腰付、宝形造桟瓦葺。二層の組物は出組で二軒繁垂木、四周に連子窓あるいは火頭窓を入れ、縁を出三斗で支え、内部に梵鐘を吊る。類稀な三層の鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013466"},{"id":"00015105","register_sub_id":"101","register_pk":"529383","name":"興国寺山門及び袖塀","kana":"こうこくじさんもんおよびそでべい","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県田川郡福智町上野1892","lat":33.72020833,"lng":130.78722222,"geo_status":"db","era":"大正13年","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"山門 木造、銅板葺、間口3.3m 袖塀 木造、銅板葺、総延長7.5m、潜戸付","structure_material":"山門 木造","registered":"2024.08.15(令和6.08.15)","register_no":"40 - 0227","desc":"境内入口に南面して建つ一間一戸入母屋造銅板葺の二重門。両脇に銅板葺袖塀を付す。下層主柱は円柱、控柱は角柱、組物は三斗の詰組で、内部は格天井張。上層は円柱に大斗肘木を組む。軒はいずれも緩やかに反らせた二軒扇垂木とし、精緻で斬新なつくりの山門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015105"},{"id":"00015104","register_sub_id":"101","register_pk":"529382","name":"興国寺本堂","kana":"こうこくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県田川郡福智町上野1892","lat":33.72051944,"lng":130.78728611,"geo_status":"db","era":"大正8年／令和4年改修","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積297㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"40 - 0226","desc":"福智山南西麓に位置する曹洞宗寺院の本堂。境内北側に南面して建つ入母屋造平入桟瓦葺。入側一間の広縁を取込んだ六間取の方丈形式で、正面に三間向拝を付す。内部中央の大間は折上格天井張。正面中央には二重に虹梁形差物を渡し、力士彫刻の束で飾った本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015104"},{"id":"00013201","register_sub_id":"101","register_pk":"368425","name":"小烏神社神饌所","kana":"こがらすじんじゃしんせんしょ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"福岡県","address":"福岡県福岡市中央区警固三丁目194","lat":33.57984444,"lng":130.39153889,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積19㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"40 － 0168","desc":"拝殿脇に渡廊下を介して接続する。桁行三間、梁間二間、切妻造桟瓦葺、内部は入口回りを土間、その他を板敷の一室とする。西角に物入を作り、南西面に板戸の出入口を設ける。妻は二重虹梁で、虹梁端部に鯖の尾を付す等、小規模ながら凝ったつくりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013201"},{"id":"00013203","register_sub_id":"101","register_pk":"368427","name":"小烏神社手水舎","kana":"こがらすじんじゃてみずしゃ","category":"宗教","subcategory":"建築物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"福岡県","address":"福岡県福岡市中央区警固三丁目194","lat":33.57969722,"lng":130.39175278,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造、銅板葺、面積6.7㎡","structure_material":"木造","registered":"2019.12.05(令和1.12.05)","register_no":"40 － 0170","desc":"拝殿に通じる参道脇に位置する。桁行一間、梁間一間、切妻造銅板葺、角柱四本を内転びに立て、中央に昭和四年銘の手水鉢を置き、四方を吹放しとする。柱上に舟肘木を置き桁と虹梁を受け、虹梁上に板蟇股をおいて棟木を受ける。本殿などと意匠を統一する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013203"},{"id":"00013202","register_sub_id":"101","register_pk":"368426","name":"小烏神社天満宮","kana":"こがらすじんじゃてんまんぐう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福岡県","address":"福岡県福岡市中央区警固三丁目194","lat":33.57979722,"lng":130.39128611,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積3.4㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"40 － 0169","desc":"本殿の西、境内の隅に位置する。一間社流造、銅板葺、浜床を付ける。柱は円柱で、三斗組とし、軒は二軒繁垂木。妻を虹梁大瓶束とする。向拝と身舎は海老虹梁で繋ぎ、三方に切目縁を設け、身舎両袖を脇障子で仕切る。檜の良材を用いた造作の丁寧な小社である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013202"},{"id":"00013200","register_sub_id":"101","register_pk":"368424","name":"小烏神社拝殿及び渡殿","kana":"こがらすじんじゃはいでんおよびわたりでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"福岡県","address":"福岡県福岡市中央区警固三丁目194","lat":33.57979167,"lng":130.39151389,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積35㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"40 － 0167","desc":"本殿正面に接続し、南面して建つ。拝殿は入母屋造銅板葺平入、渡殿は銅板葺とする。拝殿は身舎・向拝ともに二軒、軸部を吹放ち開放として、四周に縁を廻す。床は板張り、天井は格天井とし、向拝蟇股を藤の彫刻で飾る。簡素な中にも質の高い建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013200"},{"id":"00013205","register_sub_id":"101","register_pk":"368429","name":"小烏神社奉献塔","kana":"こがらすじんじゃほうけんとう","category":"宗教","subcategory":"その他工作物","type_guess":"塔","type_guess_confidence":"low","period":"昭和前","pref":"福岡県","address":"福岡県福岡市中央区警固三丁目194","lat":33.57976667,"lng":130.39130278,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"石造、高さ6.0m","structure_material":"石造","registered":"2019.12.05(令和1.12.05)","register_no":"40 － 0172","desc":"拝殿脇に立つ高さ６メートルの石塔。二段積の台座の上に立ち、塔上は笠木付の柱頭を飾り、頂部に銅製の八咫烏を載せる。正面となる南に「奉献」の浮彫り、背面に昭和四年の銘と寄進者の名を刻み、境内景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013205"},{"id":"00013199","register_sub_id":"101","register_pk":"368423","name":"小烏神社本殿","kana":"こがらすじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"福岡県","address":"福岡県福岡市中央区警固三丁目194","lat":33.57983056,"lng":130.39141389,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"40 － 0166","desc":"天神近郊住宅地の丘陵にある神社。本殿は境内後方の高台に建つ。三間社流造銅板葺で、四方に高欄付切目縁を廻し、向拝廻りに浜床を広くとる。妻飾は虹梁に豕扠首、組物は身舎四隅及び向拝を出三斗とする。全体に装飾を抑えた、端正な意匠の本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013199"},{"id":"00013204","register_sub_id":"101","register_pk":"368428","name":"小烏神社瑞垣","kana":"こがらすじんじゃみずがき","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"low","period":"昭和前","pref":"福岡県","address":"福岡県福岡市中央区警固三丁目194","lat":33.57984444,"lng":130.39138056,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造、金属板葺、延長33m","structure_material":"木造","registered":"2019.12.05(令和1.12.05)","register_no":"40 － 0171","desc":"渡殿に接続し、本殿を中心に一辺三〇尺の透塀で囲む。角柱を地、腰、内法の各長押で固め、腕木で出桁を受け、疎垂木、鉄板葺とする。腰長押、内法長押間に連子窓を嵌める。簡素ながら装飾をもち、本殿の配置に沿った計画的な平面構成をとる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013204"},{"id":"00014430","register_sub_id":"101","register_pk":"511419","name":"篠山神社透塀","kana":"ささやまじんじゃすきべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県久留米市篠山町字六丁目444","lat":33.32893611,"lng":130.50783889,"geo_status":"db","era":"明治12年／昭和5年頃改修","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"木造、銅板葺及び瓦葺、延長88m","structure_material":"木造","registered":"2022.10.31(令和4.10.31)","register_no":"40 - 0203","desc":"中門左右に延びて本殿を取り囲む透塀。東西一三間、南北一七間規模で、石積は江戸切仕上げ切石乱積みで築き、腰長押下は襷桟打、内法長押の間に竪格子を嵌め込み、出桁造、疎垂木とする塀を立ち上げる。本殿まわりの神域を画し、森厳な社殿空間を作り出す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014430"},{"id":"00014429","register_sub_id":"101","register_pk":"511418","name":"篠山神社中門","kana":"ささやまじんじゃちゅうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"福岡県","address":"福岡県久留米市篠山町字六丁目444","lat":33.328775,"lng":130.5079,"geo_status":"db","era":"明治12年／昭和5年頃改修","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"木造、銅板葺、間口2.7m","structure_material":"木造","registered":"2022.10.31(令和4.10.31)","register_no":"40 - 0202","desc":"本殿と拝殿のほぼ中間に位置する。一間平唐門、銅板葺、高さ約一メートルの石垣上に建つ。冠木上の蟇股に有馬家家紋の左三つ巴、控柱の虹梁形頭貫上に雲文をあしらい、懸魚の六葉は同家家紋の竜胆車でかたどる。丁寧なつくりで、建物の由緒を装飾に織り込む。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014429"},{"id":"00014428","register_sub_id":"101","register_pk":"511417","name":"篠山神社拝殿","kana":"ささやまじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県久留米市篠山町字六丁目444","lat":33.32862778,"lng":130.50783611,"geo_status":"db","era":"明治12年／昭和5年改修","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積87㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"40 - 0201","desc":"本殿から約四〇メートル南に位置する。桁行五間、梁間三間、入母屋造平入、銅板葺で、基壇は切石二段で築く。正面に三間幅の広い向拝を付け、内部は折上げ格天井とし、四周に刎高欄付切目縁をまわす。正面桟唐戸、背面引分戸の他は蔀を吊る開放的な大型拝殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014428"},{"id":"00014427","register_sub_id":"101","register_pk":"511416","name":"篠山神社本殿","kana":"ささやまじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県久留米市篠山町字六丁目444","lat":33.32893333,"lng":130.50792778,"geo_status":"db","era":"明治12年／昭和5年改修","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積43㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"40 - 0200","desc":"筑後川に面する久留米城址の本丸跡に南面して建つ。三間社、入母屋造妻入、三間向拝付、銅板葺で、有馬家藩主五柱を祀る。中備蟇股で、出組、二軒繁垂木が深い軒を持ち出す。大屋根に向拝を取り込み、特異ながらも端正かつ堂々たる構えの近代大型社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014427"},{"id":"00014549","register_sub_id":"101","register_pk":"513963","name":"浄福寺山門","kana":"じょうふくじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県大川市大字小保字上町市場40-1","lat":33.20472222,"lng":130.3725,"geo_status":"db","era":"明治5年頃","year":1872,"year_source":"db","year_min":1872,"year_max":1872,"year_label":null,"structure":"木造、瓦葺、間口2.8m","structure_material":"木造","registered":"2023.02.27(令和5.02.27)","register_no":"40 - 0213","desc":"木工で知られる歴史的町並みの通りに開く浄土真宗寺院の山門。切妻造桟瓦葺の薬医門で、軒は半繁垂木で天井を張る。八双金具等で飾った板扉を建て、西脇間に潜り戸、両側面の男梁先に支柱を入れて袖壁を設ける。五平の本柱等木柄太く質実で、格式を窺わせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014549"},{"id":"00008602","register_sub_id":"101","register_pk":"134998","name":"浄福寺鐘楼","kana":"じょうふくじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"福岡県","address":"福岡県福岡市南区桧原6-897-7","lat":33.53186744,"lng":130.38529128,"geo_status":"db","era":"江戸後期／明治中期・昭和50年移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、面積8.4㎡","structure_material":"木造","registered":"2011.01.26(平成23.01.26)","register_no":"40 － 0066","desc":"方一間で、四周吹放ちとする。礎盤上に円柱を内転びにたて、腰貫や長押、台輪で固め、尾垂木付二手先を詰組とし、一軒扇垂木を配る。妻木連格子の入母屋造本瓦葺。中央を鏡天井とする化粧屋根裏天井で、彫刻欄間や地紋彫を飾る。秀逸な意匠になる吹放ち鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008602"},{"id":"00014548","register_sub_id":"101","register_pk":"513962","name":"浄福寺離れ座敷","kana":"じょうふくじはなれざしき","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"福岡県","address":"福岡県大川市大字小保字上町市場40-1","lat":33.20440556,"lng":130.37212778,"geo_status":"db","era":"大正5年頃／平成16年・同28年・令和3年改修","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積60㎡","structure_material":"木造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"40 - 0212","desc":"榎津の町並みにある浄土真宗寺院の座敷棟で本堂背面に位置。入母屋造桟瓦葺、続き間座敷の周囲に廊下を巡らし、北西に便所角屋を付す。付け書院床構えの座敷は床脇を廊下に張出して一畳増やした七畳間で、旧吉原家住宅と似た独特な床構えとし、地域色を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014548"},{"id":"00014547","register_sub_id":"101","register_pk":"513961","name":"浄福寺本堂","kana":"じょうふくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"福岡県","address":"福岡県大川市大字小保字上町市場40-1","lat":33.20451667,"lng":130.37223333,"geo_status":"db","era":"天保5年（1834）／平成16年改修","year":1834,"year_source":"db","year_min":1834,"year_max":1834,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積161㎡","structure_material":"木造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"40 - 0211","desc":"木工で知られる榎津の町並みに所在する浄土真宗寺院の本堂。入母屋造平入本瓦葺、正面側に縁を巡らし向拝を付す。向拝廻りや内外陣境欄間等に華やかな彫刻を施す。内部は外陣、矢来内、内陣及び左右に余間を設け、典型的な真宗寺院本堂で歴史的町並みを構成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014547"},{"id":"00013660","register_sub_id":"101","register_pk":"505027","name":"世界平和パゴダ","kana":"せかいへいわぱごだ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"福岡県","address":"福岡県北九州市門司区大字門司字与郷松3249-2","lat":33.95469167,"lng":130.97075833,"geo_status":"db","era":"昭和33年","year":1958,"year_source":"db","year_min":1958,"year_max":1958,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積197㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"40 － 0176","desc":"門司港を見下ろす和布刈公園に建つ。戦没者慰霊、日緬親善交流、世界平和を祈念して建築されたミャンマー様式の仏塔。鉄筋コンクリート造、半径七・四メートルの円形平面で三面に出入口を突出させる。外壁は石張で上部は金色タイルで飾る。類稀な遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013660"},{"id":"00016612","register_sub_id":"101","register_pk":"574974","name":"大正寺積翠庵腰掛待合","kana":"たいしょうじせきすいあんこしかけまちあい","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和後","pref":"福岡県","address":"福岡県北九州市八幡東区東台良町519-21","lat":33.86111083,"lng":130.79404583,"geo_status":"db","era":"昭和46年頃","year":1971,"year_source":"db","year_min":1971,"year_max":1971,"year_label":null,"structure":"木造平屋建、人工スレート葺、建築面積4.6㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"40 - 0260","desc":"茶室の南東に位置する腰掛待合。露地に北面して建つ平屋建片流造招屋根付で、屋根は人工スレート葺とする。吹放ちの北面以外は土壁とし、内部の南寄りに腰掛を設ける。柱や桁、母屋に丸太を用いた数寄屋風のつくりとし、重森三玲作の露地と調和した腰掛待合。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016612"},{"id":"00016611","register_sub_id":"101","register_pk":"574973","name":"大正寺積翠庵茶室","kana":"たいしょうじせきすいあんちゃしつ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和後","pref":"福岡県","address":"福岡県北九州市八幡東区東台良町519-21","lat":33.86111083,"lng":130.79404583,"geo_status":"db","era":"昭和46年","year":1971,"year_source":"db","year_min":1971,"year_max":1971,"year_label":null,"structure":"木造平屋建、瓦葺一部銅板葺、建築面積84㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"40 - 0259","desc":"皿倉山中腹の臨済宗寺院に八幡茶道文化協会が寄進した修養用茶室。平屋建切妻造桟瓦葺で南東に銅板葺庇を廻らす。広間と小間の茶室、水屋などを配し、円窓や火灯窓風の欄間など各室洗練された意匠。布基礎に色石をあしらい、重森三玲作の露地と調和した茶室。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016611"},{"id":"00016746","register_sub_id":"101","register_pk":"579230","name":"波折神社手水舎","kana":"なみおりじんじゃてみずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県福津市津屋崎四丁目1386","lat":33.790702,"lng":130.461752,"geo_status":"db","era":"大正11年","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造、瓦葺、面積4.7㎡","structure_material":"木造","registered":"2026.07.09(令和8.07.09)","register_no":"40 - 0263","desc":"境内中央に位置する手水舎。桁行一間、梁間一間、切妻造桟瓦葺。成の高い礎石に角柱を四方転びに立て、頭貫と内法貫で固め、大斗肘木で桁と虹梁を受け、虹梁上の蟇股で棟木を支持。南に井戸、北に手水鉢を配し、四方を吹放つ。小規模ながら境内景観に寄与。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016746"},{"id":"00016747","register_sub_id":"101","register_pk":"579231","name":"波折神社二ノ鳥居","kana":"なみおりじんじゃにのとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県福津市津屋崎四丁目1386","lat":33.790581,"lng":130.461802,"geo_status":"db","era":"大正9年","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"石造、間口4.2m、高さ5.5m","structure_material":"石造","registered":"2026.07.09(令和8.07.09)","register_no":"40 - 0264","desc":"境内中央に位置する石造の明神鳥居。間口４・２メートル、高さ5・5メートル、花崗岩の円柱を内転びに立てて貫で固め、頂部に笠木と島木を載せ、笠木と島木の全体に反りを付ける。拝殿及び幣殿の再建に伴い建立した丁寧なつくりの鳥居で、境内景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016747"},{"id":"00016745","register_sub_id":"101","register_pk":"579229","name":"波折神社拝殿及び幣殿","kana":"なみおりじんじゃはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"福岡県","address":"福岡県福津市津屋崎四丁目1386","lat":33.79083,"lng":130.461831,"geo_status":"db","era":"大正9年／昭和54年改修","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積55㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"40 - 0262","desc":"本殿の南に建つ拝殿及び幣殿。拝殿は正面三間、側面三間、切妻造妻入銅板葺で、背面に両下造銅板葺の幣殿を接続する。拝殿正面には擬宝珠高欄付の縁を設け、一間向拝を付す。内部は一室の畳敷とし、上部は化粧屋根裏天井で、二重虹梁を現した雄大なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016745"},{"id":"00016744","register_sub_id":"101","register_pk":"579228","name":"波折神社本殿","kana":"なみおりじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県福津市津屋崎四丁目1386","lat":33.790933,"lng":130.461851,"geo_status":"db","era":"明治23年／令和3年改修","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積19㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"40 - 0261","desc":"津屋崎港の東側に位置する神社の本殿。境内の北寄りに南面し、石積基壇に建つ三間社流造で屋根銅板葺、四周に縁を廻らす。柱は円柱で組物は平三斗、軒は二軒繁垂木。妻飾は二重虹梁大瓶束で笈形を付し、唐獅子、麒麟、波涛文などの彫刻で飾る華やかな社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016744"},{"id":"00013008","register_sub_id":"101","register_pk":"368081","name":"日本福音ルーテル久留米教会礼拝堂","kana":"にほんふくいんるーてるくるめきょうかいれいはいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県久留米市日吉町16-3","lat":33.31519167,"lng":130.51346944,"geo_status":"db","era":"大正7年／昭和25年・同29年改修","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"煉瓦造平屋一部2階建、銅板葺、建築面積165㎡","structure_material":"煉瓦造平屋一部2階建","registered":"2019.09.10(令和1.09.10)","register_no":"40 － 164","desc":"市中心部の教会で、街路南側の敷地西南隅に北面して建つ。煉瓦造、東西棟の切妻造で、東北隅の鐘楼北面に玄関を設ける。内部はシザーズ・トラスをかけ、柱のない礼拝空間をつくる。合理的な平面構成や丁寧な仕上がヴォーリズ初期の設計活動の特徴をよく示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013008"},{"id":"00013009","register_sub_id":"101","register_pk":"368082","name":"日本福音ルーテル久留米教会煉瓦塀","kana":"にほんふくいんるーてるくるめきょうかいれんがべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"福岡県","address":"福岡県久留米市日吉町16-3","lat":33.31532778,"lng":130.51357778,"geo_status":"db","era":"昭和2年頃","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"石造及び煉瓦造、総延長21m","structure_material":"石造及び煉瓦造","registered":"2019.09.10(令和1.09.10)","register_no":"40 － 165","desc":"敷地北面の街路沿いに建つ。煉瓦造、基礎切石積で、敷地中央部を後退して正門を設ける。モルタル笠木付の煉瓦長手積角柱を等間隔に並べ、柱間の塀をモルタル塗とし、壁面に７連アーチ、上端に笠木を表す。礼拝堂と調和し、整然とした表構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013009"},{"id":"00014117","register_sub_id":"101","register_pk":"508377","name":"梅林寺ティーハウス","kana":"ばいりんじてぃーはうす","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"福岡県","address":"福岡県久留米市京町字五丁目209-43","lat":33.32352778,"lng":130.49848611,"geo_status":"db","era":"昭和33年／平成20年改修","year":1958,"year_source":"db","year_min":1958,"year_max":1958,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積74㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"40 - 0195","desc":"筑後川左岸高台の梅林寺外苑に建つ、鉄筋コンクリート造平屋建の茶店。中心軸上に配した丸柱と壁柱で屋根スラブと一体化した大梁を支え、梅園及び筑後川に面する外壁をカーテンウォールとする。特殊な架構で軽快なデザインを実現した菊竹清訓初期作品。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014117"},{"id":"00016450","register_sub_id":"101","register_pk":"536517","name":"福岡縣護国神社大鳥居","kana":"ふくおかけんごこくじんじゃおおとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"昭和前","pref":"福岡県","address":"福岡県福岡市中央区六本松一丁目1区1-1","lat":33.58206667,"lng":130.38028056,"geo_status":"db","era":"昭和18年／令和5年改修","year":1943,"year_source":"db","year_min":1943,"year_max":1943,"year_label":null,"structure":"木造、金属板（チタン）葺、柱間8.9m、高さ13m","structure_material":"木造","registered":"2025.11.17(令和7.11.17)","register_no":"40 - 0253","desc":"境内北辺の参道入口に建つ木造の明神鳥居。設計は二本松孝蔵。柱間８・９メートル、高さ１２・８メートル、台湾ヒノキの原木を用いた独立柱を内転びに立て、柱上に反りのある島木と笠木を載せる。原木材を用いた国内最大級の鳥居の一つで地域の象徴的存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016450"},{"id":"00016444","register_sub_id":"101","register_pk":"536511","name":"福岡縣護国神社祈願殿","kana":"ふくおかけんごこくじんじゃきがんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和中","pref":"福岡県","address":"福岡県福岡市中央区六本松一丁目1区1-1","lat":33.58196389,"lng":130.38188611,"geo_status":"db","era":"昭和36年／平成12年・同24年改修","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"鉄筋コンクリート造平屋建、銅板葺、建築面積44㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"40 - 0247","desc":"拝殿北翼廊の北端に接続し、かつて参拝入口に用いた小舎。設計は角南隆。広場に西面して建つ、鉄筋コンクリート造切妻造妻入銅板葺。内部は一室の土間で、正面側は開放的なつくりとする。南翼舎と一対をなし、拝殿を中心とした左右対称の社殿景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016444"},{"id":"00016448","register_sub_id":"101","register_pk":"536515","name":"福岡縣護国神社北手水舎兼灯篭","kana":"ふくおかけんごこくじんじゃきたてみずしゃけんとうろう","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和中","pref":"福岡県","address":"福岡県福岡市中央区六本松一丁目1区1-1","lat":33.58178333,"lng":130.38111944,"geo_status":"db","era":"昭和38年","year":1963,"year_source":"db","year_min":1963,"year_max":1963,"year_label":null,"structure":"鉄筋コンクリート造、銅板葺、面積4.2㎡","structure_material":"鉄筋コンクリート造","registered":"2025.11.17(令和7.11.17)","register_no":"40 - 0251","desc":"境内中央の広場の北辺中央に建つ手水舎兼灯篭。設計は角南隆。平面八角形、鉄筋コンクリート造宝形造銅板葺で、隅に緩やかな反りを付す。火袋下方は鉢状につくり手水舎を兼ねる。深い軒ながらも軽快な屋根で、全体に均整の取れた端正な意匠の手水舎兼灯篭。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016448"},{"id":"00016452","register_sub_id":"101","register_pk":"536519","name":"福岡縣護国神社招魂社鳥居","kana":"ふくおかけんごこくじんじゃしょうこんしゃとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県福岡市中央区六本松一丁目1区1-1","lat":33.58115278,"lng":130.38191111,"geo_status":"db","era":"明治3年／明治39年頃・同44年頃移築","year":1870,"year_source":"db","year_min":1870,"year_max":1870,"year_label":null,"structure":"石造、柱間2.2m、高さ3.1m","structure_material":"石造","registered":"2025.11.17(令和7.11.17)","register_no":"40 - 0255","desc":"境内中央広場の南東に建つ石造の明神鳥居。柱間２・２メートル、高さ３・１メートル、石造の独立柱を内転びに立て、柱上部に島木と笠木を載せ、正面に扁額を掲げる。旧妙見招魂社からの移築で、各地の招魂社を束ねて創建した、当社の歴史を伝える貴重な鳥居。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016452"},{"id":"00016447","register_sub_id":"101","register_pk":"536514","name":"福岡縣護国神社透塀","kana":"ふくおかけんごこくじんじゃすきべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和中","pref":"福岡県","address":"福岡県福岡市中央区六本松一丁目1区1-1","lat":33.58188611,"lng":130.38243611,"geo_status":"db","era":"昭和36年","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"コンクリートブロック造及び鉄筋コンクリート造、延長69m、木戸付","structure_material":"コンクリートブロック造及び鉄筋コンクリート造","registered":"2025.11.17(令和7.11.17)","register_no":"40 - 0250","desc":"本殿及び奉安殿の三方を囲み、拝殿背面に接続する透塀。設計は角南隆。延長６９メートル、柱は鉄筋コンクリート造、柱間はコンクリートブロック造で格子窓を開ける。内側に控壁を付し、頂部に屋根をつくる。本殿及び奉安殿域を画す簡明で静謐な佇まいの透塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016447"},{"id":"00016451","register_sub_id":"101","register_pk":"536518","name":"福岡縣護国神社西鳥居","kana":"ふくおかけんごこくじんじゃにしのとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"昭和前","pref":"福岡県","address":"福岡県福岡市中央区六本松一丁目1区1-1","lat":33.580325,"lng":130.38028056,"geo_status":"db","era":"昭和18年","year":1943,"year_source":"db","year_min":1943,"year_max":1943,"year_label":null,"structure":"木造、柱間6.2m、高さ8.5m","structure_material":"木造","registered":"2025.11.17(令和7.11.17)","register_no":"40 - 0254","desc":"境内西辺の南側に建つ木造の明神鳥居。設計は二本松孝蔵。柱間６・２メートル、高さ８・５メートル、台湾ヒノキの原木を用いた独立柱を内転びに立て、柱上部に島木と笠木を載せて、各端部に反りをつける。都心部にあって戦災焼失を免れた貴重な木造の鳥居。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016451"},{"id":"00016443","register_sub_id":"101","register_pk":"536510","name":"福岡縣護国神社拝殿及び翼廊","kana":"ふくおかけんごこくじんじゃはいでんおよびよくろう","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和中","pref":"福岡県","address":"福岡県福岡市中央区六本松一丁目1区1-1","lat":33.58173056,"lng":130.38213333,"geo_status":"db","era":"昭和36年／平成12年改修","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"鉄筋コンクリート造平屋建、銅板葺、建築面積346㎡、基壇付","structure_material":"鉄筋コンクリート造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"40 - 0246","desc":"半円形の舞台状基壇に西面して建つ拝殿と翼廊。設計は角南隆。鉄筋コンクリート造切妻造妻入銅板葺の正面に切妻造向拝を付す。両脇には切妻造棟を突出して周囲に庇を廻らし、さらに両下造の翼廊を左右前方へＶ字状に延ばす。左右対称の壮麗な姿の大規模社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016443"},{"id":"00016446","register_sub_id":"101","register_pk":"536513","name":"福岡縣護国神社奉安殿","kana":"ふくおかけんごこくじんじゃほうあんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和中","pref":"福岡県","address":"福岡県福岡市中央区六本松一丁目1区1-1","lat":33.58183611,"lng":130.38234167,"geo_status":"db","era":"昭和36年","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"鉄筋コンクリート造平屋建、銅板葺、建築面積20㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"40 - 0249","desc":"本殿の東側に西面して建ち戦没者の名簿を収める社殿。設計は角南隆。鉄筋コンクリート造切妻造妻入銅板葺で正面に階段を設け、戸口上部に庇を付す。円柱の床束、井桁に組む台輪、壁面に横目地を入れるなど、全体を校倉造風に仕上げた堅牢な姿の奉安殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016446"},{"id":"00016442","register_sub_id":"101","register_pk":"536509","name":"福岡縣護国神社本殿","kana":"ふくおかけんごこくじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和中","pref":"福岡県","address":"福岡県福岡市中央区六本松一丁目1区1-1","lat":33.58181111,"lng":130.38226389,"geo_status":"db","era":"昭和36年","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"鉄筋コンクリート造平屋建、銅板葺、建築面積41㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"40 - 0245","desc":"福岡城跡の南に位置する神社の本殿。設計は角南隆。境内東側に西面して建つ、鉄筋コンクリート造切妻造銅板葺で、周囲の庇を錣葺とする。軒裏は垂木形とせず平滑に仕上げて軽快にみせ、外に延ばす軒桁や梁、肘木の先端に竪溝を切るなど、独創的な意匠の本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016442"},{"id":"00016449","register_sub_id":"101","register_pk":"536516","name":"福岡縣護国神社南手水舎兼灯篭","kana":"ふくおかけんごこくじんじゃみなみてみずしゃけんとうろう","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和中","pref":"福岡県","address":"福岡県福岡市中央区六本松一丁目1区1-1","lat":33.5811,"lng":130.38176667,"geo_status":"db","era":"昭和38年","year":1963,"year_source":"db","year_min":1963,"year_max":1963,"year_label":null,"structure":"鉄筋コンクリート造、銅板葺、面積4.0㎡","structure_material":"鉄筋コンクリート造","registered":"2025.11.17(令和7.11.17)","register_no":"40 - 0252","desc":"境内中央の広場の南辺中央に建つ手水舎兼灯篭。設計は角南隆。平面八角形とする鉄筋コンクリート造宝形造銅板葺で隅に緩やかな反りを付す。火袋下方は鉢状につくり手水舎を兼ねる。全体に均整の取れた端正な意匠で、北手水舎兼灯篭と一対で境内景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016449"},{"id":"00016445","register_sub_id":"101","register_pk":"536512","name":"福岡縣護国神社南翼舎","kana":"ふくおかけんごこくじんじゃみなみよくしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"福岡県","address":"福岡県福岡市中央区六本松一丁目1区1-1","lat":33.58148611,"lng":130.38218889,"geo_status":"db","era":"昭和36年／平成12年改修","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"鉄筋コンクリート造平屋建、銅板葺、建築面積44㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"40 - 0248","desc":"拝殿南翼廊の南端に接続し、かつて神職の控室に用いた小舎。設計は角南隆。広場に西面して建つ、鉄筋コンクリート造切妻造妻入銅板葺。内部は一室の土間で、正面側は開放的なつくりとする。北翼舎と一対で拝殿を中心とした左右対称の壮大な社殿景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016445"},{"id":"00015519","register_sub_id":"101","register_pk":"533534","name":"水田天満宮西門","kana":"みずたてんまんぐうにしもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"福岡県","address":"福岡県筑後市大字水田字上町64-1","lat":33.19854722,"lng":130.48511944,"geo_status":"db","era":"嘉永4年（1851）","year":1851,"year_source":"db","year_min":1851,"year_max":1851,"year_label":null,"structure":"木造、瓦葺、間口3.1m、袖塀付","structure_material":"木造","registered":"2025.08.06(令和7.08.06)","register_no":"40 - 0240","desc":"境内西面に開く四脚門。切妻造本瓦葺で両脇に桟瓦葺袖塀を付す。本柱は円柱、控柱は角柱で頭貫、腰長押で固め、組物は出組で板支輪を付し、軒は二軒繁棰木、妻飾は虹梁大瓶束笈形付とする。支輪板には地紋彫や梅と波の浮彫彫刻を付すなど装飾華やかな西門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015519"},{"id":"00015518","register_sub_id":"101","register_pk":"533533","name":"水田天満宮東門","kana":"みずたてんまんぐうひがしもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"福岡県","address":"福岡県筑後市大字水田字上町64-1","lat":33.19854722,"lng":130.4861,"geo_status":"db","era":"慶応4年（1868）","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"木造、瓦葺、間口2.7m","structure_material":"木造","registered":"2025.08.06(令和7.08.06)","register_no":"40 - 0239","desc":"境内東面の中央に開く四脚門。切妻造本瓦葺で、円柱の本柱、角柱の控柱を頭貫、腰長押で固め、組物は大斗絵様肘木、軒は二軒繁垂木、妻飾は虹梁大瓶束笈形付とする。内部は化粧軒裏を現し門口に板扉を開く。全体に質実なつくりで境内東面の景観の要となる門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015518"},{"id":"00015517","register_sub_id":"101","register_pk":"533532","name":"水田天満宮楼門","kana":"みずたてんまんぐうろうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"福岡県","address":"福岡県筑後市大字水田字上町64-1","lat":33.19824167,"lng":130.48576667,"geo_status":"db","era":"江戸末期／平成12年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積24㎡","structure_material":"木造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"40 - 0238","desc":"市街地南西に位置する神社の門。境内入口に南面して建つ入母屋造本瓦葺、三間三戸の二重門。大面取の角柱を用い、各層とも組物は大斗肘木、軒は二軒繁垂木とし、上層周囲に刎高欄付縁を廻らす。下層に朱塗の獅子鼻など付し、地域景観の核をなす華やかな楼門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015517"},{"id":"00014116","register_sub_id":"101","register_pk":"508376","name":"明光寺禅堂","kana":"みょうこうじぜんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"福岡県","address":"福岡県福岡市博多区吉塚三丁目347-2他","lat":33.59940833,"lng":130.42751389,"geo_status":"db","era":"江戸後期／明治43年移築、大正5年・昭和34年頃改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積78㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"40 - 0194","desc":"本堂の西に南東向きに建つ木造禅堂。入母屋造桟瓦葺妻入で、正面に向唐破風の向拝を付す。正面は中央に引違戸、両脇に花頭窓を開ける。内部は土間で正面入側筋を境に二室に区分し、奥の一室に畳敷の床を側廻りに設ける。境内に残る貴重な江戸後期の禅堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014116"},{"id":"00014115","register_sub_id":"101","register_pk":"508375","name":"明光寺霊屋","kana":"みょうこうじたまや","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"福岡県","address":"福岡県福岡市博多区吉塚三丁目347-2他","lat":33.59952778,"lng":130.42770833,"geo_status":"db","era":"大正15年／昭和37年頃改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造平屋建、瓦葺、建築面積122㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"40 - 0193","desc":"本堂の北西に並び建つ位牌堂。鉄筋コンクリート造、入母屋造桟瓦葺。側廻りは円柱に舟肘木を載せ長押を廻し、両妻面三箇所の花頭窓を跨ぐ。内部は一室コンクリート土間、虹梁形内法貫と頭貫を縦横に架ける。本堂と共に初期コンクリート造の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014115"},{"id":"00014114","register_sub_id":"101","register_pk":"508374","name":"明光寺本堂","kana":"みょうこうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県福岡市博多区吉塚三丁目347-2他","lat":33.59937778,"lng":130.4278,"geo_status":"db","era":"大正13年／平成22年改修","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート造平屋建、瓦葺、建築面積263㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"40 - 0192","desc":"博多駅北東に位置し南西向きに建つ曹洞宗寺院の鉄筋コンクリート造本堂。入母屋造桟瓦葺で正面に向拝、背面に下屋を付す。外観は軸組を鼠漆喰、壁面白漆喰で塗分ける。内部は六間取で正面に広縁を付す。細部まで施工精度の高い初期鉄筋コンクリート造の本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014114"},{"id":"00014432","register_sub_id":"101","register_pk":"511421","name":"若八幡宮拝殿","kana":"わかはちまんぐうはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"福岡県","address":"福岡県糟屋郡久山町大字久原字口ケ坪3497","lat":33.64721944,"lng":130.50159167,"geo_status":"db","era":"元治2年(1865)／大正１４年・平成13年改修","year":1865,"year_source":"db","year_min":1865,"year_max":1865,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積22㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"40 - 0205","desc":"本殿正面に建つ拝殿。桁行三間、梁間三間、切妻造妻入銅板葺で正面に一間の向拝を付す。土台建で、軸部は内法貫、頭貫で固め、組物は大斗肘木、軒は二軒疎垂木とする。妻飾りは二重虹梁蟇股。柱や蟇股など古材を用い、小規模ながら装飾充実した妻入の拝殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014432"},{"id":"00014433","register_sub_id":"101","register_pk":"511422","name":"若八幡宮幣殿","kana":"わかはちまんぐうへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県糟屋郡久山町大字久原字口ケ坪3497","lat":33.64724444,"lng":130.50157222,"geo_status":"db","era":"大正13年／昭和53年改修","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積5.0㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"40 - 0206","desc":"本殿と拝殿の間を繋ぐ幣殿。桁行一間、梁間一間、両下造銅板葺。土台建で、軸部は頭貫、腰長押、内法長押を廻して固める。組物は背面柱上を大斗肘木とし、虹梁上に板蟇股を立てて化粧棟木を支持し、軒は一軒疎垂木。全体に控えめながら、丁寧な造りの弊殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014433"},{"id":"00014431","register_sub_id":"101","register_pk":"511420","name":"若八幡宮本殿","kana":"わかはちまんぐうほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"福岡県","address":"福岡県糟屋郡久山町大字久原字口ケ坪3497","lat":33.64727778,"lng":130.501525,"geo_status":"db","era":"寛政11年(1799)／昭和元年改修","year":1799,"year_source":"db","year_min":1799,"year_max":1799,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積14㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"40 - 0204","desc":"犬鳴山南西麓に位置する神社本殿。境内北西の平坦地に東南向きに建つ三間社流造銅板葺で、正面に三間の向拝を付す。組物は出組で中備は蟇股とし、軒は二軒繁垂木。向拝虹梁廻り、妻飾り、脇障子等を彫刻で華やかに飾る。建立年代明確で、彫刻優秀な本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014431"},{"id":"00008382","register_sub_id":"101","register_pk":"134024","name":"医王寺山門","kana":"いおうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"佐賀県","address":"佐賀県唐津市相知町黒岩183","lat":33.37352251,"lng":130.00672053,"geo_status":"db","era":"文政4年（1821)","year":1821,"year_source":"db","year_min":1821,"year_max":1821,"year_label":null,"structure":"木造、瓦葺、間口3.2m","structure_material":"木造","registered":"2010.09.10(平成22.09.10)","register_no":"41 － 0079","desc":"本堂の正面に位置する。一間薬医門、切妻造桟瓦葺。本柱上、冠木を載せ、前後に女梁・男梁を架け、妻及び中備に板蟇股を置く。一軒疎垂木で、切妻造桟瓦葺とする。控柱は面取方柱で、控柱間の中備に雲紋の蟇股を飾る。全体に木太い印象である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008382"},{"id":"00008381","register_sub_id":"101","register_pk":"134023","name":"医王寺本堂","kana":"いおうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"佐賀県","address":"佐賀県唐津市相知町黒岩183","lat":33.37352108,"lng":130.00705087,"geo_status":"db","era":"安永7年(1778)／明治43年・昭和38年・昭和56年改修","year":1778,"year_source":"db","year_min":1778,"year_max":1778,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積223㎡","structure_material":"木造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"41 － 0078","desc":"境内の後方中央に西面して建つ。桁行１５ｍ梁間１４ｍ、入母屋造一重桟瓦葺。六間取方丈形式で、その前方二間通りを広縁と前土間とした。内陣の背面に接して須弥壇を構え、来迎柱に平三斗を組む。内陣とその前の大間境は円柱で虹梁をかける。標準的な曹洞宗本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008381"},{"id":"00014121","register_sub_id":"101","register_pk":"508381","name":"願正寺大玄関","kana":"がんしょうじおおげんかん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"佐賀県","address":"佐賀県佐賀市呉服元町182他","lat":33.25559444,"lng":130.30417222,"geo_status":"db","era":"昭和9年","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造2階建、瓦葺、建築面積180㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"41 - 0123","desc":"本堂南東に建つ玄関棟。切妻造桟瓦葺、桁行二四・七メートル、梁間七メートルで、南面西寄に大ぶりの入母屋造玄関を付し、両脇に花頭窓を配し、その東を庇付内玄関とする。内部は広間と南西の寺務室、その二階に八畳二室を配す。無柱の大空間が特徴の大玄関。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014121"},{"id":"00014120","register_sub_id":"101","register_pk":"508380","name":"願正寺大広間","kana":"がんしょうじおおひろま","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"佐賀県","address":"佐賀県佐賀市呉服元町182他","lat":33.25575,"lng":130.30426667,"geo_status":"db","era":"昭和9年","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積288㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"41 - 0122","desc":"本堂東、貴賓室と大玄関の間に建つ広間棟。南北に長大な平面を持つ切妻造桟瓦葺の建物で、内部は八〇畳の大広間とし北に御内仏と両脇に床を構える。講師室を北に配し両脇は廊下を下屋で通す。小屋組にキングポストトラスを用い大空間を実現した近代の大広間。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014120"},{"id":"00014119","register_sub_id":"101","register_pk":"508379","name":"願正寺貴賓室","kana":"がんしょうじきひんしつ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"佐賀県","address":"佐賀県佐賀市呉服元町182他","lat":33.25583333,"lng":130.30412222,"geo_status":"db","era":"18世紀前期","year":1750,"year_source":"estimated","year_min":1701,"year_max":1750,"year_label":"18世紀前期","structure":"木造平屋建、瓦葺、建築面積109㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"41 - 0121","desc":"本堂北東に建つ客殿。切妻造桟瓦葺、西の貴賓室一〇畳書院座敷と東の奧の間二〇畳からなり、北に半間幅の廊下、南に一間幅畳敷の鞘の間を付し竹節欄間と絵付杉戸で区画する。繊細な筬欄間、面皮付床柱、漆塗の床框等簡素ながら上質な藩主御成間と伝わる書院。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014119"},{"id":"00014123","register_sub_id":"101","register_pk":"508383","name":"願正寺山門","kana":"がんしょうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"佐賀県","address":"佐賀県佐賀市呉服元町182他","lat":33.25530278,"lng":130.30409722,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造、瓦葺、間口4.6m","structure_material":"木造","registered":"2021.10.14(令和3.10.14)","register_no":"41 - 0125","desc":"本堂南に建つ切妻造本瓦葺平入の四脚門。本柱を丸柱、控柱を角柱として礎盤上に立て、控柱間に強い渦紋の虹梁を架け挿し肘木で受ける。方立脇の幕板の渦紋彫刻、側面の花狭間、桟唐戸の透彫や鈁金具など随所に浄土真宗寺院らしい華やかな装飾を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014123"},{"id":"00014122","register_sub_id":"101","register_pk":"508382","name":"願正寺鐘楼","kana":"がんしょうじしょうろう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"佐賀県","address":"佐賀県佐賀市呉服元町182他","lat":33.25536944,"lng":130.30423611,"geo_status":"db","era":"明和5年(1768)","year":1768,"year_source":"db","year_min":1768,"year_max":1768,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積14㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"41 - 0124","desc":"本堂の南東に建つ入母屋造本瓦葺の鐘楼。赤石を用いた裾広の切石乱積基壇上に建ち、下層は袴腰、上層は丸柱を長押で固め三斗を受け中備を蟇股とする。高欄付の縁は木鼻状板持送りで受ける。佐賀城下の時鐘として用いられたと伝わる木柄の太い重厚な鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014122"},{"id":"00014118","register_sub_id":"101","register_pk":"508378","name":"願正寺本堂","kana":"がんしょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"佐賀県","address":"佐賀県佐賀市呉服元町182他","lat":33.25562222,"lng":130.303925,"geo_status":"db","era":"元禄15年(1702)／明和2年（1765）改修","year":1702,"year_source":"db","year_min":1702,"year_max":1702,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積805㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"41 - 0120","desc":"佐賀城跡北に建つ真宗寺院本堂。正面九間、奥行八間半、入母屋造本瓦葺。外周は大斗と実肘木、中備蟇股等簡素。平面は標準的だが、内外陣境を欄間彫刻で飾り、矢来前面に長大な虹梁を架けて彫刻で飾る。当地の中心的真宗寺院で九州有数の規模と古さを持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014118"},{"id":"00001757","register_sub_id":"101","register_pk":"102747","name":"陶山神社鳥居","kana":"すえやまじんじゃとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"明治","pref":"佐賀県","address":"佐賀県西松浦郡有田町大樽2-1464","lat":33.18894139,"lng":129.89909228,"geo_status":"db","era":"明治21","year":1888,"year_source":"db","year_min":1888,"year_max":1888,"year_label":null,"structure":"磁器製、高さ3.7m","structure_material":"磁器製","registered":"2000.04.28(平成12.04.28)","register_no":"41 － 0015","desc":"有田焼が始まる江戸前期に開かれ、有田の象徴的存在として知られる陶山神社の鳥居。明神鳥居の形式で、高さ３．７ｍ、笠木の長さ３．９ｍの規模を持つ。青色顔料の呉須で唐草文が描かれ、有田焼による大規模磁器製作の技術が遺憾なく発揮されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001757"},{"id":"00001020","register_sub_id":"101","register_pk":"102010","name":"日本福音ルーテル小城教会","kana":"にほんふくいんるーてるおぎきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"佐賀県","address":"佐賀県小城市小城町170-8","lat":33.29190886,"lng":130.19873638,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造平屋一部２階建，スレート葺，建築面積247㎡","structure_material":"木造平屋一部２階建","registered":"1998.12.11(平成10.12.11)","register_no":"41 － 0010","desc":"切妻屋根の小さな木造教会堂で，東面にホール及び牧師館が雁行型状に接続し一体的に構成される。切妻造の教会堂は，背面の妻壁に聖壇部が円形状に張出す独特の外観をしており，親しまれている。設計はヴォーリズ建築事務所で，施工は辻組である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001020"},{"id":"00009679","register_sub_id":"101","register_pk":"194675","name":"与賀神社本殿・幣殿・拝殿","kana":"よかじんじゃほんでん・へいでん・はいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"佐賀県","address":"佐賀県佐賀市与賀町92","lat":33.2488065,"lng":130.29488318,"geo_status":"db","era":"本殿 宝暦8、幣殿・拝殿 宝暦9／大正2改修","year":1758,"year_source":"db","year_min":1758,"year_max":1758,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積118㎡","structure_material":"木造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"41 － 0083","desc":"佐賀城西側の境内中央に西面する権現造社殿。本殿は前室付の五間社流造で、内陣を一室として後方に間口三間の内殿を囲い、内宮三基を祀る。妻飾は瑞獣や雲龍などを主題とした巧緻な彫刻で満たす。拝殿は正面軒唐破風付で、内外の随所を華やかな彫刻で飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009679"},{"id":"00009407","register_sub_id":"101","register_pk":"194200","name":"亀岡神社神楽殿","kana":"かめおかじんじゃかぐらでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"長崎県","address":"長崎県平戸市岩の上町字亀岡151","lat":33.36766083,"lng":129.55673857,"geo_status":"db","era":"明治13年","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積47㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"42 － 0102","desc":"本殿ほかの社殿を画す回廊及び瑞垣の前方に位置し、参道に西面して建つ。桁行三間梁間三間、入母屋造本瓦葺、四方吹放しとし、背面に下屋を設けて後座とし、正面に石階を付す。懸魚には波に亀の彫刻を施す。平戸神楽を奉納す当社に欠かせない社殿である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009407"},{"id":"00009406","register_sub_id":"101","register_pk":"194199","name":"亀岡神社拝殿","kana":"かめおかじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"長崎県","address":"長崎県平戸市岩の上町字亀岡1517","lat":33.36809258,"lng":129.5568786,"geo_status":"db","era":"明治13年","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積48㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"42 － 0101","desc":"本殿の南側に建ち、幣殿及び登廊を介して本殿と接続する。桁行三間梁間三間、入母屋造本瓦葺、四周に縁を廻し、正面に石階を付す。内部には合祀した四社のうち三社の扁額が掲げられ神社の歴史を伝えている。均整のとれた外観をもち、中心社殿の正面を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009406"},{"id":"00009405","register_sub_id":"101","register_pk":"194198","name":"亀岡神社弊殿及び登廊","kana":"かめおかじんじゃへいでんおよびのぼりろう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"長崎県","address":"長崎県平戸市岩の上町字亀岡1517","lat":33.36816301,"lng":129.55692334,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積9.6㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"42 － 0100","desc":"拝殿背面に幣殿を連ね、本殿と幣殿の間に登廊を架渡す。幣殿は桁行二間梁間一間、渡廊は桁行三間梁間一間、両下造桟瓦葺である。幣殿の棹縁天井をヴォールト状とし、登廊では太鼓橋状に起りをもたせ側面に欄干を配するなど、本殿と併せて独特の形式をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009405"},{"id":"00009404","register_sub_id":"101","register_pk":"194197","name":"亀岡神社本殿","kana":"かめおかじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"長崎県","address":"長崎県平戸市岩の上町字亀岡1517","lat":33.36821536,"lng":129.5569557,"geo_status":"db","era":"明治13年","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"木造平屋建、鉄板葺一部瓦葺、建築面積32㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"42 － 0099","desc":"平戸城二の丸跡に鎮座する神社で、境内北端中央の高い石垣上に本殿が建つ。桁行三間梁間二間、切妻造平入、鉄板葺で、正側面に縁を廻らし、棟に千木、鰹木を戴く。正面に入母屋造桟瓦葺の向拝を付す。向拝木階の左右に神像を安置するなど独特の形式をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009404"},{"id":"00002101","register_sub_id":"101","register_pk":"103091","name":"馬込教会","kana":"まごめきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"長崎県","address":"長崎県長崎市伊王島町2-617","lat":32.69752345,"lng":129.78167044,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造平屋建、瓦葺、建築面積340㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2000.12.04(平成12.12.04)","register_no":"42 － 0010","desc":"長崎湾西方に浮かぶ伊王島南部の沖之島地区に建つ３廊式の教会堂で，外部は重層屋根，内部は３層構成，８分割リブ・ヴォールト天井とし，正面をバットレス，尖塔，ピナクル等で賑やかに飾る。地元大工棟梁の工夫の跡が随所に窺われる初期ＲＣ造教会堂建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002101"},{"id":"00000276","register_sub_id":"101","register_pk":"101266","name":"宮地嶽八幡神社陶器製鳥居","kana":"みやじだけはちまんじんじゃとうきせいとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"明治","pref":"長崎県","address":"長崎県長崎市八幡町8-6","lat":32.75072637,"lng":129.88510697,"geo_status":"db","era":"明治21","year":1888,"year_source":"db","year_min":1888,"year_max":1888,"year_label":null,"structure":"陶器製，高さ3.5m，幅4.3m","structure_material":"陶器製","registered":"1997.07.15(平成9.07.15)","register_no":"42 － 0001","desc":"有田磁窯による大型細工でつくられた鳥居。親柱部分に残る銘によって製造人が岩尾久吉，角物細工人が金ヶ江長作，丸物細工人が峰熊一であることが判明する。有田に製作者が同一のものがひとつあるが，他に類例がない稀少的な存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000276"},{"id":"00012077","register_sub_id":"101","register_pk":"211018","name":"青井阿蘇神社禊橋","kana":"あおいあそじんじゃみそぎばし","category":"宗教","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"熊本県","address":"熊本県人吉市上青井町字上青井町140-1","lat":32.212699,"lng":130.753224,"geo_status":"db","era":"大正10年","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"コンクリート造3連アーチ橋、橋長27m、幅員3.8m","structure_material":"コンクリート造3連アーチ橋","registered":"2017.10.27(平成29.10.27)","register_no":"43-168","desc":"門前の蓮池に南北に架けられたコンクリート造の三連アーチ橋。橋長二七メートル、幅員三・八メートルで、赤色塗の高欄を設け、両岸に袖高欄を付す。アーチの輪石部は瘤出仕上げの迫石風とし、要石は洋風意匠とする。県内で現存最古のコンクリート橋梁。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012077"},{"id":"00005057","register_sub_id":"101","register_pk":"106047","name":"大川阿蘇神社農村舞台","kana":"おおかわあそじんじゃのうそんぶたい","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"熊本県","address":"熊本県上益城郡山都町大平字宮ノ本120","lat":32.6917603,"lng":131.09088548,"geo_status":"db","era":"昭和28","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積89㎡","structure_material":"木造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"43 － 0076","desc":"西面する境内地の西部に東面して南北棟で建つ。桁行７間，梁間３間半の規模で，切妻造，鉄板葺，木造平屋建で，東側を舞台とし西側に楽屋を設け，中央に上段を設け，舞台北東隅に浄瑠璃棚を付属する。正面間口全体を開き，上部全幅に梁を渡す特異な構造をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005057"},{"id":"00002102","register_sub_id":"101","register_pk":"103092","name":"シャルトル聖パウロ修道院記念館","kana":"しゃるとるせいぱうろしゅうどういんきねんかん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"明治","pref":"熊本県","address":"熊本県八代市通町10-8","lat":32.50760376,"lng":130.60312845,"geo_status":"db","era":"明治33","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造2階建、瓦葺、建築面積105㎡","structure_material":"木造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"43 － 0045","desc":"八代白百合学園高等学校敷地内に東を正面にして建つ。木造２階建下見板張，南北棟の寄棟造洋館で，階下内部は中廊下を挟んで２室づつの４室構成とし，階下階上とも東南の２面にベランダを廻す。ベランダ下見板コロニアルの伝播をとらえる上で貴重な遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002102"},{"id":"00012664","register_sub_id":"101","register_pk":"367958","name":"シャルトル聖パウロ修道女会八代修道院煉瓦塀","kana":"しゃるとるせいぱうろしゅうどうじょかいやつしろしゅうどういんれんがべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"大正","pref":"熊本県","address":"熊本県八代市通町壱0号7-1","lat":32.50806,"lng":130.604767,"geo_status":"geocoded","era":"大正8年","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"煉瓦造、延長21m","structure_material":"煉瓦造","registered":"2018.11.02(平成30.11.02)","register_no":"43 － 0174","desc":"市中心部にある修道院の敷地境界塀の一部で、街路に面した敷地東面北半に建つ。高さ1･8メートル、躯体を煉瓦の長手積とし、規則的に柱形をつくり出す。頂部は二段の蛇腹上に煉瓦で切妻屋根をつくる。開発が進む中心市街地の歴史的景観を伝える希少な遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012664"},{"id":"00000918","register_sub_id":"101","register_pk":"101908","name":"高寺院毘沙門堂","kana":"たかでらいんびしゃもんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"熊本県","address":"熊本県球磨郡山江村大字山田甲1640","lat":32.2488061,"lng":130.76169491,"geo_status":"db","era":"承応4","year":1655,"year_source":"db","year_min":1655,"year_max":1655,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積28㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"43 － 0015","desc":"山頂に建つ三間堂。内部は柱を省略し，後方に幅一間の須弥壇を設け，格天井を張る。須弥壇の墨書から承応４年の建立が知られる。反り増しを持つ太い垂木は地域的特色。中世～近世前期の寺社建築が多数現存する球磨地方において時代の指標となる建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000918"},{"id":"00013206","register_sub_id":"101","register_pk":"368430","name":"日本福音ルーテル熊本教会","kana":"にほんふくいんるーてるくまもときょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和中","pref":"熊本県","address":"熊本県熊本市中央区水道町1-17","lat":32.80295,"lng":130.71296667,"geo_status":"db","era":"昭和25年／平成17年改修","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造3階建、金属板葺、建築面積213㎡、階段付","structure_material":"木造3階建","registered":"2019.12.05(令和1.12.05)","register_no":"43 － 0176","desc":"市中心部にある教会堂。木造二階一部三階建、切妻造金属板葺で、南東角に尖頭屋根を戴く塔を配する。一階は集会室、二階は主廊部の南側にのみ側廊が付く礼拝堂で、ハンマービーム・トラスを現し、開口は尖頭アーチで統一する。ヴォーリズ晩年の作品のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013206"},{"id":"00003637","register_sub_id":"101","register_pk":"104627","name":"梅林天満宮鳥居","kana":"ばいりんてんまんぐうとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"江戸","pref":"熊本県","address":"熊本県玉名市津留499","lat":32.93371286,"lng":130.58861752,"geo_status":"db","era":"万治2／昭和3改造","year":1659,"year_source":"db","year_min":1659,"year_max":1659,"year_label":null,"structure":"石造、高さ4.8m","structure_material":"石造","registered":"2003.09.19(平成15.09.19)","register_no":"43 － 0057","desc":"石造の明神鳥居だが，柱の頂部を台輪状に彫り出している。柱は足元で径約７３ｃｍと太く，また内転びも大きい。各部材も木太く，全体の比例にも地方色があらわれている。数度の改造があるが，神社の正面を飾る堂々とした形態で，地域景観の核となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003637"},{"id":"00003635","register_sub_id":"101","register_pk":"104625","name":"梅林天満宮拝殿","kana":"ばいりんてんまんぐうはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"熊本県","address":"熊本県玉名市津留499","lat":32.9340051,"lng":130.58862466,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、銅板葺、建築面積32㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"43 － 0055","desc":"桁行梁間とも３間，入母屋造，平入，銅板葺で，正面には１間向拝を設け，正面と両側面に独特な擬宝珠高欄付の切目縁を廻す。組物は出組で，中備は蟇股，軒は２軒吹寄せ垂木とする。向拝は唐破風造で，透彫の手挟や梅鉢文を彫った大柄な蟇股など見所がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003635"},{"id":"00003634","register_sub_id":"101","register_pk":"104624","name":"梅林天満宮本殿","kana":"ばいりんてんまんぐうほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"熊本県","address":"熊本県玉名市津留499","lat":32.93409245,"lng":130.58862466,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、銅板葺、建築面積21㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"43 － 0054","desc":"桁行３間，梁間２間，入母屋造，正面３間向拝付の本殿建築で，正面と両側面に切目縁を廻す。組物は２手先，２軒繁垂木で，屋根は銅板葺。波涛文風彫物の軒支輪，彫物を入れた中備の蟇股，透彫の向拝手挟，頭貫の雲文絵様など，上方に装飾を集めた造形になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003634"},{"id":"00003636","register_sub_id":"101","register_pk":"104626","name":"梅林天満宮楼門","kana":"ばいりんてんまんぐうろうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"熊本県","address":"熊本県玉名市津留499","lat":32.93378334,"lng":130.58862228,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、銅板葺、建築面積32㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"43 － 0056","desc":"３間１戸の２重門。上重は桁行３間，梁間２間の入母屋造で，４周に擬宝珠高欄付の縁を廻し，尾垂木付の３手先組物で２軒繁垂木の軒を受ける。下重は前後に軒唐破風を設け，菖蒲棟を力神像で支える。全体の比例，高い基壇など，地方色豊かな造形を示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003636"},{"id":"00008792","register_sub_id":"101","register_pk":"149513","name":"本妙寺仁王門","kana":"ほんみょうじにおうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"大正","pref":"熊本県","address":"熊本県熊本市花園4-128","lat":32.81540897,"lng":130.69250935,"geo_status":"db","era":"大正9年","year":1920,"year_source":"converted","year_min":1920,"year_max":1920,"year_label":null,"structure":"鉄筋コンクリート造、間口13m","structure_material":"鉄筋コンクリート造","registered":"2011.07.25(平成23.07.25)","register_no":"43 － 0112","desc":"本妙寺山麓に位置する。鉄筋コンクリート造の三間三戸八脚門。切妻造で、前後に軒唐破風を付設。総円柱で、大斗組とし、妻は虹梁上に束をたてる。一軒繁垂木。両脇後間の上部に仁王像、中央間境にライオンの阿吽像を飾る。時代を反映した自由な発想が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008792"},{"id":"00000809","register_sub_id":"101","register_pk":"101799","name":"明導寺本堂","kana":"みょうどうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"大正","pref":"熊本県","address":"熊本県球磨郡湯前町買元1955","lat":32.27730308,"lng":130.98203795,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積292㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"43 － 0014","desc":"特異な意匠の寺院本堂。マンサード屋根，下見板貼りの外壁，ハーフティンバー形式の正面入口，アーチ形が連続する内外陣境，尖頭アーチ形の窓，トラスの小屋組など，各部が洋風になる。京都龍谷大学で学んだ住職の長男が独自に設計したと伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000809"},{"id":"00016461","register_sub_id":"101","register_pk":"536528","name":"妙蓮寺鐘楼門","kana":"みょうれんじしょうろうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"熊本県","address":"熊本県菊池市隈府247","lat":32.98292222,"lng":130.81125,"geo_status":"db","era":"江戸中期／寛文12年（1672）移築、大正4年改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造2階建、瓦葺、建築面積8.2㎡","structure_material":"木造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"43 - 0219","desc":"境内北端、通りに面して建つ二重門。入母屋造桟瓦葺で、扉口を棟筋より前面に寄せ、上層の正背面に火灯窓を開け、側廻の柱間に菱格子を建て、周囲に擬宝珠高欄付縁を廻らす。組物は大斗肘木、軒は一軒繁垂木。絵様など古式で境内の表構えをつくる鐘楼門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016461"},{"id":"00016460","register_sub_id":"101","register_pk":"536527","name":"妙蓮寺本堂","kana":"みょうれんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県菊池市隈府247","lat":32.98261944,"lng":130.81141389,"geo_status":"db","era":"明治30年／平成15年・同18年改修","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積211㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"43 - 0218","desc":"隈府の中央部の角地に位置する日蓮宗寺院の本堂。境内南側に北面して建つ入母屋造桟瓦葺で正面向拝付き。内部は内外陣・両脇陣からなり、内陣に須弥壇を配す。向拝は皿斗二重の大斗や雲形肘木など独特で、虹梁形頭貫に龍彫刻を横溢させ、装飾華やかな本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016460"},{"id":"00008385","register_sub_id":"101","register_pk":"134027","name":"老松天満社金刀比羅社","kana":"おいまつてんまんしゃことひらしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"大分県","address":"大分県日田市天瀬町出口字中村1183","lat":33.20523546,"lng":131.0190443,"geo_status":"db","era":"文政7年(1824)／江戸末期移築","year":1824,"year_source":"db","year_min":1824,"year_max":1824,"year_label":null,"structure":"石造平屋建、建築面積0.7㎡","structure_material":"石造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"44 － 0181","desc":"拝殿の北方に、石積基壇上に南面して建つ。石造の社殿で、桁行０．７３ｍ梁間０．５５ｍの規模で、正面に唐破風造向拝を付ける入母屋造屋根を載せる。石材は日田石と通称される地元産の凝灰岩。肘木や妻飾なども丁寧に作り出されるなど秀でた技巧が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008385"},{"id":"00008386","register_sub_id":"101","register_pk":"134028","name":"老松天満社鳥居","kana":"おいまつてんまんしゃとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県日田市天瀬町出口字中村1183","lat":33.20510024,"lng":131.0192555,"geo_status":"db","era":"弘化3年(1846)","year":1846,"year_source":"db","year_min":1846,"year_max":1846,"year_label":null,"structure":"石造、間口2.5m","structure_material":"石造","registered":"2010.09.10(平成22.09.10)","register_no":"44 － 0182","desc":"境内の東寄り、参道の正面に位置する。花崗岩を使った石造。内転びのある直径０．４４ｍ胴張りのある円柱を、柱間２．５ｍに建て、貫を通し、一体で作られた島木と笠木を上部に載せる。笠木は勢いのある反りをもち、軸太の柱とよく調和する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008386"},{"id":"00008384","register_sub_id":"101","register_pk":"134026","name":"老松天満社拝殿","kana":"おいまつてんまんしゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県日田市天瀬町出口字中村1183","lat":33.20512151,"lng":131.01907013,"geo_status":"db","era":"明治31年","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造平屋建、茅葺、建築面積42㎡、渡殿付","structure_material":"木造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"44 － 0180","desc":"本殿の正面に位置する。桁行三間梁間三間、入母屋造、正面に向拝一間と千鳥破風を付ける。茅葺に杉皮を葺き込む特徴的な仕様とする。正面は桟唐戸と蔀戸、背面は蔀戸で、両脇に壇を設ける。内部は拭板敷で、格天井を張る。穏やかな外観が農村景観に融和する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008384"},{"id":"00008383","register_sub_id":"101","register_pk":"134025","name":"老松天満社本殿","kana":"おいまつてんまんしゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県日田市天瀬町出口字中村1183","lat":33.20512758,"lng":131.01894554,"geo_status":"db","era":"明治31年／昭和54年改修","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積18㎡","structure_material":"木造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"44 － 0179","desc":"境内の後方に東面して建つ。三間社流造、銅板葺。組高欄付の切目縁を周囲にまわし、正面に木階を設ける。円柱で出組とし、中備に蟇股を置く。妻は二重虹梁で二段にもち出し、拝みに唐獅子などの彫刻を飾る。均整のとれた外観のなか、彫物装飾が適度に配される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008383"},{"id":"00009090","register_sub_id":"101","register_pk":"162450","name":"春日神社神楽殿","kana":"かすがじんじゃかぐらでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県豊後高田市草地字三笠山5206","lat":33.57683522,"lng":131.46845364,"geo_status":"db","era":"天保6年(1835)","year":1835,"year_source":"db","year_min":1835,"year_max":1835,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積32㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"44 － 0189","desc":"拝殿の東南に西面して建つ。桁行二間梁間一間、入母屋造妻入本瓦葺。正・側面に切目縁をまわし、北面後寄りから斜めに橋掛を延ばす。橋掛は桁行三間梁間一間、両下造桟瓦葺。神楽殿は角柱に舟肘木を載せ、中備に間斗束と絵様実肘木をおく。神社境内に残る神楽殿の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009090"},{"id":"00009089","register_sub_id":"101","register_pk":"162449","name":"春日神社籠り屋","kana":"かすがじんじゃこもりや","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大分県","address":"大分県豊後高田市草地字三笠山5206","lat":33.57691749,"lng":131.46850988,"geo_status":"db","era":"昭和2年","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積23㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"44 － 0188","desc":"神楽殿の橋掛の先に続く。桁行5.9メートル梁間3.9メートルの木造平屋建、切妻造桟瓦葺で、西正面に瓦庇を付ける。内部は北側にコンクリート土間、南側に八畳の床上部を配する。籠り屋としてとともに神楽殿の楽屋、地域住民の集会所などとして利用される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009089"},{"id":"00009095","register_sub_id":"101","register_pk":"162455","name":"春日神社参道鳥居","kana":"かすがじんじゃさんどうとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県豊後高田市草地字三笠山5206","lat":33.57650481,"lng":131.46817257,"geo_status":"db","era":"享保5年(1720）","year":1720,"year_source":"db","year_min":1720,"year_max":1720,"year_label":null,"structure":"石造、間口3.1m、高さ3.8m","structure_material":"石造","registered":"2011.10.28(平成23.10.28)","register_no":"44 － 0194","desc":"春日神社境内の南端に位置する。石造の明神鳥居で、幅3.1メートル高さ3.8メートル。礎石の上に内転びで円柱を建て、貫と島木、笠木で固める。笠木の両端に強い反りをもたせ、力強い立面を構成する。深い社叢の正面に建ち、近世以来の歴史的景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009095"},{"id":"00009091","register_sub_id":"101","register_pk":"162451","name":"春日神社鐘楼","kana":"かすがじんじゃしょうろう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県豊後高田市草地字三笠山5206","lat":33.57683001,"lng":131.46825371,"geo_status":"db","era":"文政13年(1830)","year":1830,"year_source":"db","year_min":1830,"year_max":1830,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積7.4㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"44 － 0190","desc":"拝殿の南方、神楽殿と参道を挟んで対峙する。切石基礎上に建つ方一間袴腰付の鐘楼。入母屋造本瓦葺。方柱上部を頭貫と台輪で固め、三斗を組み、中備に蟇股を飾る。一軒半繁垂木とし、内部も化粧垂木を現す。近世における神仏習合の境内景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009091"},{"id":"00009092","register_sub_id":"101","register_pk":"162452","name":"春日神社神門","kana":"かすがじんじゃしんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"大分県","address":"大分県豊後高田市草地字三笠山5206","lat":33.57674358,"lng":131.46831307,"geo_status":"db","era":"弘化2年（1845）","year":1845,"year_source":"db","year_min":1845,"year_max":1845,"year_label":null,"structure":"木造、瓦葺、間口3.4m、左右袖塀付","structure_material":"木造","registered":"2011.10.28(平成23.10.28)","register_no":"44 － 0191","desc":"拝殿の前方に位置する四脚門。切妻造本瓦葺。本柱は粽付円柱で、控柱は几帳面取方柱。虹梁状の頭貫や台輪で固め、組物は三斗組。妻は虹梁大瓶束で、二軒繁垂木。四半石敷で、格天井を張る。前間には格子付の棚を設け随身像を安置。威厳ある境内構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009092"},{"id":"00009085","register_sub_id":"101","register_pk":"162445","name":"春日神社摂社厳島神社","kana":"かすがじんじゃせっしゃいつくしまじんじゃ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県豊後高田市草地字三笠山5206","lat":33.57714345,"lng":131.46831411,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造平屋建、銅板葺、建築面積1.2㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"44 － 0184","desc":"本殿の西に南面して建ち、一間社流造銅板葺である。切石基礎に土台を据えて円柱を立て、長押や貫で固める。組物は舟肘木、軒は二軒繁垂木とし、妻飾を豕叉首とする。擬宝珠高欄付の切目縁を廻らし、正面に木階二級を付ける。小規模ながら丁寧なつくりの社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009085"},{"id":"00009086","register_sub_id":"101","register_pk":"162446","name":"春日神社摂社八坂神社","kana":"かすがじんじゃせっしゃやさかじんじゃ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県豊後高田市草地字三笠山5206","lat":33.5771195,"lng":131.46848801,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、銅板葺、建築面積1.2㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"44 － 0185","desc":"本殿の東に南面して建つ。一間社流造銅板葺で、高欄付の切目縁を三方にまわす。切石基礎に土台を据えて円柱を立て、長押や貫で固める。組物は三斗組、軒は二軒繁垂木とし、妻飾は虹梁を省き蟇股のみとする。海老虹梁の身舎側は頭貫木鼻と同様の絵様を彫る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009086"},{"id":"00009096","register_sub_id":"101","register_pk":"162456","name":"春日神社西参道鳥居","kana":"かすがじんじゃにしさんどうとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"昭和前","pref":"大分県","address":"大分県豊後高田市草地字三笠山5206","lat":33.57726108,"lng":131.4678901,"geo_status":"db","era":"昭和9年","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"石造、間口3.1m、高さ3.9m","structure_material":"石造","registered":"2011.10.28(平成23.10.28)","register_no":"44 － 0195","desc":"西門へと延びる西参道の入口に建つ。石造の明神鳥居で、幅3.1メートル高さ3.9メートル。径36センチメートルの円柱を内転びに建て、貫と島木、笠木で固める。嶋木や笠木はほぼ同じせいで、全体に反りをもたせ、安定感のある姿をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009096"},{"id":"00009093","register_sub_id":"101","register_pk":"162453","name":"春日神社西門","kana":"かすがじんじゃにしもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"大分県","address":"大分県豊後高田市草地字三笠山5206","lat":33.57711117,"lng":131.46815062,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口1.9m","structure_material":"木造","registered":"2011.10.28(平成23.10.28)","register_no":"44 － 0192","desc":"拝殿の西方に位置する。小規模な一間一戸薬医門で、切妻造本瓦葺。本柱は円柱、控柱は面取角柱で、それぞれを虹梁形頭貫で固め、主・控柱間には男梁を架す。男梁上に虹梁を置き、棟木を支持し、一軒疎垂木を配る。木部は赤色に塗装され、西紅門とも称される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009093"},{"id":"00009088","register_sub_id":"101","register_pk":"162448","name":"春日神社拝殿","kana":"かすがじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県豊後高田市草地字三笠山5206","lat":33.57701225,"lng":131.46836513,"geo_status":"db","era":"大正10年","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積103㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"44 － 0187","desc":"申殿の前方に東西棟で建つ。桁行九間梁間四間、入母屋造本瓦葺で、正面中央に入母屋屋根の一間向拝を付ける。切石積基壇上に方柱を立て、貫で固める。内部は一室で板敷とし、格天井を張る。両側面を土壁とするほかは開口とする、横長で開放的なつくりの拝殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009088"},{"id":"00009084","register_sub_id":"101","register_pk":"162444","name":"春日神社本殿","kana":"かすがじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県豊後高田市草地字三笠山5206","lat":33.57714137,"lng":131.46840366,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、銅板葺、建築面積17㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"44 － 0183","desc":"境内の中央に南面して建つ。三間社切妻造、向拝一間銅板葺である。周囲に組高欄付切目縁をまわし、正面に蔀、側面前一間に桟唐戸を吊る。妻飾は二重虹梁大瓶束で、組物で二手分持ち出し、小天井と支輪を付ける。たちの高い外観構成になる本殿である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009084"},{"id":"00009087","register_sub_id":"101","register_pk":"162447","name":"春日神社申殿","kana":"かすがじんじゃもうしでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"明治","pref":"大分県","address":"大分県豊後高田市草地字三笠山5206","lat":33.5770716,"lng":131.46838075,"geo_status":"db","era":"明治38年","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積12㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"44 － 0186","desc":"本殿正面に位置する。東西棟の切妻造桟瓦葺。桁行一間梁間一間。円柱を長押や頭貫、台輪で固め、組物は三斗とし、妻は束で棟木や母屋を支持する。内部は一室で板敷、格天井を張り、柱間は側面後半を板壁とし、他はガラス戸を建てる。当地方に見られる申殿の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009087"},{"id":"00009094","register_sub_id":"101","register_pk":"162454","name":"春日神社余興舞台","kana":"かすがじんじゃよきょうぶたい","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"大分県","address":"大分県豊後高田市草地字尾園324","lat":33.57541886,"lng":131.46190251,"geo_status":"db","era":"昭和27年","year":1952,"year_source":"db","year_min":1952,"year_max":1952,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積115㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"44 － 0193","desc":"境内から1キロメートルほど離れた御旅所に南を正面として建つ。桁行16メートル梁間7.9メートルの入母屋造セメント瓦葺で、妻面に下屋を付設する。南半部を舞台、北半部を楽屋とする。正面を除き、外壁は下見板張。小屋は和小屋。伝統的な農村舞台建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009094"},{"id":"00009688","register_sub_id":"101","register_pk":"194684","name":"正行寺山門","kana":"しょうぎょうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県中津市大字永添字城屋敷1148-1","lat":33.57345493,"lng":131.2054068,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口4.3m","structure_material":"木造","registered":"2013.06.21(平成25.06.21)","register_no":"44 － 0204","desc":"本堂正面の参道に建ち、四脚門、切妻造桟瓦葺である。柱頭を、成が高く華やかな絵様を施した梁や頭貫で固め、重厚な軸部を構成する。また妻飾では竜頭を象った大瓶束を立て、妻壁板に笈型を陽刻し雲紋を地紋彫するなど、豊かな装飾が特徴的な、風格ある山門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009688"},{"id":"00009687","register_sub_id":"101","register_pk":"194683","name":"正行寺鐘楼","kana":"しょうぎょうじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県中津市大字永添字城屋敷1148-1","lat":33.573345,"lng":131.20528164,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、面積8.1㎡","structure_material":"木造","registered":"2013.06.21(平成25.06.21)","register_no":"44 － 0203","desc":"境内東寄り、山門の南側に位置し、布石積み基壇上に東西棟で建つ吹放し形式の鐘楼。入母屋造桟瓦葺。軸部は禅宗様を基調とし、石製礎盤に円柱を立て、折上格天井を張る。台輪上に独特なつくりの尾垂木付三斗を詰組とする。真宗寺院伽藍を特徴付ける鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009687"},{"id":"00009689","register_sub_id":"101","register_pk":"194685","name":"正行寺袖塀","kana":"しょうぎょうじそでべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県中津市大字永添字城屋敷1148-1","lat":33.57350538,"lng":131.20543014,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、総延長20m","structure_material":"木造","registered":"2013.06.21(平成25.06.21)","register_no":"44 － 0205","desc":"山門の本柱から南北面に矩折れにのびる袖塀。総延長二〇メートル、切妻造桟瓦葺で、北側塀の北面に潜戸を開く。布石基礎上に須柱を立て、壁は腰をモルタル洗い出しとし、上部に五筋の定規線を表す。山門とともに門前の景観を形成し、結界を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009689"},{"id":"00009686","register_sub_id":"101","register_pk":"194682","name":"正行寺本堂","kana":"しょうぎょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県中津市大字永添字城屋敷1190","lat":33.57381613,"lng":131.20479861,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積696㎡","structure_material":"木造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"44 － 0202","desc":"境内西奥に東面する。総桁行約二七メートル、入母屋造本瓦葺で、正面に向拝三間を設ける。後門形式の平面をもつ真宗本堂で、軸部は良質なケヤキの長大材を用い、組物出組とし、各室に高く折上格天井を張る。細部彫刻も優れた、雄大なつくりの大型本堂である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009686"},{"id":"00007427","register_sub_id":"101","register_pk":"108409","name":"浄土寺一伯公廟","kana":"じょうどじいっぱくこうびょう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"大分県","address":"大分県大分市王子西町93-1","lat":33.242668,"lng":131.58887059,"geo_status":"db","era":"江戸後期／大正14・昭和49移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積7.3㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"44 － 0153","desc":"本堂の東方に位置する。桁行３．０ｍ梁間２．４ｍ、入母屋造妻入桟瓦葺で、正面に軒唐破風を付ける。粽付円柱を建て、尾垂木付二手先を組み、支輪には雲文様を刻む。組物などの細部意匠は古風。内部は土間の一室で、格天井を張る。近世における廟所建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007427"},{"id":"00007428","register_sub_id":"101","register_pk":"108410","name":"浄土寺表門","kana":"じょうどじおもてもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"大分県","address":"大分県大分市王子西町93-1","lat":33.24274785,"lng":131.58892073,"geo_status":"db","era":"明治後期／昭和26改修・昭和49移築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、間口3.3m、左右袖塀付","structure_material":"木造","registered":"2008.10.23(平成20.10.23)","register_no":"44 － 0154","desc":"本堂の正面に南北棟で建つ四脚門。両脇に袖塀を設け、花頭形に穿ち、開戸をたてる。屋根は入母屋造桟瓦葺。控柱とも粽付円柱で、柱上に出組、中備に蟇股を置く。軒は二軒扇垂木で、内部に格天井を張る。龍や貘、唐獅子ほかの彫物により豊かに装飾されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007428"},{"id":"00007429","register_sub_id":"101","register_pk":"108411","name":"浄土寺北門","kana":"じょうどじきたもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"大正","pref":"大分県","address":"大分県大分市王子西町93-1","lat":33.24316,"lng":131.58886487,"geo_status":"db","era":"大正14／昭和49移築","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造、瓦葺、間口2.7m、左右袖塀付","structure_material":"木造","registered":"2008.10.23(平成20.10.23)","register_no":"44 － 0155","desc":"境内の北辺、通りに面して建つ四脚門。両脇に袖塀を設け、潜りを開ける。東西棟の切妻造桟瓦葺とし、棟両端に鯱を飾る。本柱は円柱、控柱は方柱。組物は三斗組、妻虹梁蟇股とし、軒は二軒繁垂木。柱上などに皿斗を置き、その上に台輪をまわす特異な仕様になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007429"},{"id":"00007424","register_sub_id":"101","register_pk":"108406","name":"浄土寺庫裏","kana":"じょうどじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県大分市王子西町93-1","lat":33.242977,"lng":131.588654,"geo_status":"db","era":"江戸後期／江戸末期改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積164㎡","structure_material":"木造2階建","registered":"2008.10.23(平成20.10.23)","register_no":"44 － 0150","desc":"本堂の北方に東面して建つ。桁行８間半梁間４間規模の細長い建物で、寄棟造妻入桟瓦葺とし、四面に庇を付ける。正面から桁行に大きく３分し、西端にトコ付の座敷と奥座敷を並べる。大面取の方柱をほぼ１間ごとに建てるなど古風な仕様を残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007424"},{"id":"00007425","register_sub_id":"101","register_pk":"108407","name":"浄土寺玄関及び渡廊下","kana":"じょうどじげんかんおよびわたりろうか","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県大分市王子西町93-1","lat":33.242882,"lng":131.5886403,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積51㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"44 － 0151","desc":"本堂と庫裏を繋ぐ南北棟の渡廊下で、東面に入母屋屋根の玄関を付設する。渡廊下は南半部を板敷の高廊下、北半部を畳廊下とする。玄関は前半部を吹放ち、方柱を建て、三斗組とする。本堂や庫裏とともに正面を向けて並び建ち、重厚な伽藍景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007425"},{"id":"00007426","register_sub_id":"101","register_pk":"108408","name":"浄土寺大弁財天石宮","kana":"じょうどじだいべんざいてんせきぐう","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"大分県","address":"大分県大分市王子西町93-1","lat":33.243073,"lng":131.588531,"geo_status":"db","era":"明治44／昭和49移築","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"石造、面積2.3㎡","structure_material":"石造","registered":"2008.10.23(平成20.10.23)","register_no":"44 － 0152","desc":"庫裏の西北、庭園内に建つ石造本殿。小規模な一間社流造で、切石基壇上に建つ。石材は地元産の凝灰岩で、基礎と身舎、向拝、屋根の４石からなる。木鼻や組物、懸魚、垂木など細部まで丁寧な仕上げとなり、技巧的な冴えを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007426"},{"id":"00007423","register_sub_id":"101","register_pk":"108405","name":"浄土寺本堂","kana":"じょうどじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県大分市王子西町93-1","lat":33.242737,"lng":131.588654,"geo_status":"db","era":"嘉永2／昭和55改修","year":1849,"year_source":"db","year_min":1849,"year_max":1849,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積454㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"44 － 0149","desc":"境内地の中央南寄りに東面して建つ大規模な七間堂。入母屋造本瓦葺で、正面に一間向拝を付ける。正・側三方に広縁をまわし、庇柱を建てる。外陣と余間、凸型の内陣からなる浄土宗本堂の典型的な平面をもつ。四天柱上部の組物や支輪など装飾的で見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007423"},{"id":"00007818","register_sub_id":"101","register_pk":"108799","name":"真宗大谷派四日市別院石橋及び水路石垣","kana":"しんしゅうおおたにはよっかいちべついんいしばしおよびすいろいしがき","category":"宗教","subcategory":"土木構造物","type_guess":"塀・手水舎","type_guess_confidence":"low","period":"江戸","pref":"大分県","address":"大分県宇佐市大字四日市字寺町1425-1","lat":33.53055656,"lng":131.32520382,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"橋 石造桁橋、橋長2.9m、幅9.5m、高欄付、石垣 石造、延長55m","structure_material":"橋 石造桁橋","registered":"2009.08.07(平成21.08.07)","register_no":"44-0170","desc":"境内東辺に南北に水路が流れ、山門前には石橋が架かる。幅９．５ｍ長さ２．９ｍの石造桁橋。上方に反らせた桁を９本架け、板石を並べる。下部に水繰を付ける高欄を両端に置く。石垣は安山岩を割石乱積とする。山門とともに伽藍正面を画し、風格を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007818"},{"id":"00007815","register_sub_id":"101","register_pk":"108796","name":"真宗大谷派四日市別院経蔵","kana":"しんしゅうおおたにはよっかいちべついんきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"大分県","address":"大分県宇佐市大字四日市字寺町1425-1","lat":33.53017344,"lng":131.32416655,"geo_status":"db","era":"寛政11／明治前期改修","year":1799,"year_source":"db","year_min":1799,"year_max":1799,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積28㎡、輪蔵付","structure_material":"土蔵造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"44-0167","desc":"境内の西南隅に位置する。切石３段を階段状に積み上げた基壇上に建つ方三間の土蔵造。宝形造本瓦葺で、正面に唐破風造銅板葺の一間向拝を付ける。外壁は漆喰仕上げ、内部は目地漆喰の碁盤敷、折上格天井とし、中央に八角輪蔵を置く。丁寧なつくりになる経蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007815"},{"id":"00007816","register_sub_id":"101","register_pk":"108797","name":"真宗大谷派四日市別院太鼓楼","kana":"しんしゅうおおたにはよっかいちべついんたいころう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県宇佐市大字四日市字寺町1425-1","lat":33.53095809,"lng":131.32463834,"geo_status":"db","era":"江戸末期／昭和前期増築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積61㎡","structure_material":"木造2階建","registered":"2009.08.07(平成21.08.07)","register_no":"44-0168","desc":"境内の北辺中央に位置する。東西棟の入母屋造本瓦葺とする二重二階の太鼓楼で、南に切妻造桟瓦葺の平屋を増築する。 ２階は桁行２．９ｍ梁間２．９ｍ、東・西面の中央に花頭窓を穿ち、内部に太鼓を備える。北半部は当初の形態をよくとどめ、伽藍景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007816"},{"id":"00007817","register_sub_id":"101","register_pk":"108798","name":"真宗大谷派四日市別院土塀及び石垣","kana":"しんしゅうおおたにはよっかいちべついんどべいおよびいしがき","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県宇佐市大字四日市字寺町1425-1","lat":33.53101999,"lng":131.32464336,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"塀 土塀、瓦葺、延長17m、石垣 石造、延長15m","structure_material":"塀 土塀","registered":"2009.08.07(平成21.08.07)","register_no":"44-0169","desc":"境内北辺にあり、太鼓楼の北側に位置する。石垣は県内産の安山岩を割石乱積とする。石垣上に布石を置き、土塀を築く。高さ１．３ｍ厚さ０．５４ｍの練塀で、折曲り延長１７ｍ。白漆喰仕上げとし、桟瓦を葺く。太鼓楼とともに真宗寺院らしい佇まいをみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007817"},{"id":"00007814","register_sub_id":"101","register_pk":"108795","name":"真宗大谷派四日市別院本堂","kana":"しんしゅうおおたにはよっかいちべついんほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県宇佐市大字四日市字寺町1425-1","lat":33.53063352,"lng":131.32434891,"geo_status":"db","era":"明治13","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積1086㎡","structure_material":"木造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"44-0166","desc":"境内後方の中央に東面して建つ。桁行２８ｍ梁間２５ｍ、周囲に軒支柱を建て、三間向拝を付ける。入母屋造とし、平側を本瓦葺、妻側を桟瓦葺とする。真宗本堂の特徴的な平面になり、内陣まわりを漆や彩画、彫物などで飾る。九州における最大級の真宗本堂である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007814"},{"id":"00008221","register_sub_id":"101","register_pk":"132746","name":"長善寺鐘楼門","kana":"ちょうぜんじしょうろうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県日田市吹上町1233","lat":33.33044516,"lng":130.92870347,"geo_status":"db","era":"正徳3年（1713）/明和3年(1766)・享和3年(1803)・昭和21年改修","year":1713,"year_source":"db","year_min":1713,"year_max":1713,"year_label":null,"structure":"木造2階建、瓦葺、建築面積13㎡","structure_material":"木造2階建","registered":"2010.04.28(平成22.04.28)","register_no":"44 － 0174","desc":"南面して建つ三間一戸楼門。入母屋造本瓦葺。上層は桁行三間梁間二間、正・背面中央間を開放し、両脇間に花頭窓を穿ち、側面は格子窓とする。方柱で、出組とし、雲紋を彫る板支輪を付ける。二軒繁垂木で、腰組は出三斗。２階階高を抑え、外観に安定感を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008221"},{"id":"00011018","register_sub_id":"101","register_pk":"208988","name":"本願寺四日市別院御成御殿","kana":"ほんがんじよっかいちべついんおなりごてん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和前","pref":"大分県","address":"大分県宇佐市四日市1410-1","lat":33.531546,"lng":131.325041,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積107㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"44-0211","desc":"門主の控所で対面所背面に渡廊下で接続して建つ。入母屋造桟瓦葺で鉄板葺庇を廻らす。内部は八畳二室を並べ、渡廊下北に四畳半、三畳を置く。南八畳の床まわりは丸太の床柱、床脇の仕切壁や天袋、地袋、明かり窓などに数寄屋風の自由な意匠を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011018"},{"id":"00011020","register_sub_id":"101","register_pk":"208990","name":"本願寺四日市別院経蔵","kana":"ほんがんじよっかいちべついんきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"明治","pref":"大分県","address":"大分県宇佐市四日市1410-1","lat":33.531019,"lng":131.325114,"geo_status":"db","era":"明治18","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積30㎡、輪蔵付","structure_material":"土蔵造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"44-0213","desc":"本堂南に東面して建つ。六角形平面で、階段状の石積基壇上に建ち、外壁から軒裏まで柱や長押形を現した漆喰塗込とする。屋根は宝形造本瓦葺で、中心に宝珠を据え正面に唐破風玄関を付す。内部には八角輪蔵を据える。類例の少ない六角円堂の経蔵として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011020"},{"id":"00011019","register_sub_id":"101","register_pk":"208989","name":"本願寺四日市別院庫裏及び長御殿","kana":"ほんがんじよっかいちべついんくりおよびながごてん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県宇佐市四日市1410-1","lat":33.531647,"lng":131.325444,"geo_status":"db","era":"大正期／昭和前期増築","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階一部平屋建、瓦葺、建築面積530㎡","structure_material":"木造2階一部平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"44-0212","desc":"対面所北に接続する。庫裏は東西棟の入母屋造二階建で、南向に入母屋玄関を開く。東端を土間とし、西寄りに二八畳の香坊と一五畳のオナイブツノマを繋げた広間を配する。庫裏西の長御殿は末寺の陳情活動のための施設で、中廊下の両側に二室ずつを並べる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011019"},{"id":"00011025","register_sub_id":"101","register_pk":"208995","name":"本願寺四日市別院山門","kana":"ほんがんじよっかいちべついんさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県宇佐市四日市1410-1","lat":33.531265,"lng":131.325749,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造、瓦葺、間口4.8m","structure_material":"木造","registered":"2016.02.25(平成28.02.25)","register_no":"44-0218","desc":"境内正面に構える山門。四脚門で屋根は入母屋造桟瓦葺で、格天井を張る。本柱は丸柱、控柱は角柱とし、長押及び頭貫と台輪で固め、出組組物で軒を支える。頭貫や組物の木鼻、頭貫の地紋彫、虹梁の若葉付木瓜形渦紋など軒廻りを華やかに飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011025"},{"id":"00011024","register_sub_id":"101","register_pk":"208994","name":"本願寺四日市別院鐘楼","kana":"ほんがんじよっかいちべついんしょうろう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県宇佐市四日市1410-1","lat":33.53102,"lng":131.325852,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積17㎡","structure_material":"木造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"44-0217","desc":"境内正面の南端に建つ桁行三間、梁間二間の袴腰付鐘楼。下層組物は二手先で、上層の高欄付縁を支える。上層は粽付丸柱の頭を頭貫及び台輪で固め、二手先組物で軒を支持する。屋根は入母屋造桟瓦葺である。太鼓楼とともに、真宗寺院正面の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011024"},{"id":"00011021","register_sub_id":"101","register_pk":"208991","name":"本願寺四日市別院総会所","kana":"ほんがんじよっかいちべついんそうがいしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"大分県","address":"大分県宇佐市四日市1410-2","lat":33.530898,"lng":131.325438,"geo_status":"db","era":"大正4頃","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積337㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"44-0214","desc":"報恩講の際に用いる総会所で、本堂正面南に北面して建つ。入母屋造桟瓦葺、平入で、正面に大型の唐破風造本瓦葺の玄関を構える。内部は本堂外陣のように四本の独立柱筋で三分割された畳敷の広い部屋とし、中央奥に仏壇を備え欄間に箔押し彫刻欄間を嵌める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011021"},{"id":"00011023","register_sub_id":"101","register_pk":"208993","name":"本願寺四日市別院太鼓楼","kana":"ほんがんじよっかいちべついんたいころう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県宇佐市四日市1410-1","lat":33.531391,"lng":131.325836,"geo_status":"db","era":"弘化4（1847）","year":1847,"year_source":"db","year_min":1847,"year_max":1847,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積16㎡","structure_material":"土蔵造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"44-0216","desc":"境内正面の北端に建つ太鼓楼。二重で石垣基壇上に建ち、下層は方二間、上層は方一間で、上層の各面に花頭窓の開口を開け、内部に太鼓を吊るす。屋根は上層入母屋造、下層葺下ろしで外部は壁、軒裏とも漆喰塗込とするが、柱や長押、桁や腕木形を現す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011023"},{"id":"00011017","register_sub_id":"101","register_pk":"208987","name":"本願寺四日市別院対面所","kana":"ほんがんじよっかいちべついんたいめんしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"大分県","address":"大分県宇佐市四日市1410-1","lat":33.531515,"lng":131.325242,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積205㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"44-0210","desc":"門主と末寺、門徒との対面所で、本堂北に建つ。入母屋造本瓦葺妻入で、正面に大型の唐破風玄関を構える。内部は玄関から廊下を挟んで一八畳と一〇畳床付の上段を並べ、周囲に畳廊下を廻らす。意匠を凝らした格天井や欄間の繊細な組格子なども上質である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011017"},{"id":"00011022","register_sub_id":"101","register_pk":"208992","name":"本願寺四日市別院茶所","kana":"ほんがんじよっかいちべついんちゃしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"大分県","address":"大分県宇佐市四日市1410-1","lat":33.531375,"lng":131.325713,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積65㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"44-0215","desc":"山門北に本堂に向かい合って建つ。入母屋造桟瓦葺妻入で、正面一間通りを吹放しとする。内部は一室で、背面中央に仏壇、両脇に物入を設け、各欄間には箔押しの彫刻欄間を嵌める。天井は格天井とし、桐と下がり藤の紋を描く。真宗寺院伽藍の構成を示す茶所。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011022"},{"id":"00011026","register_sub_id":"101","register_pk":"208996","name":"本願寺四日市別院二之門","kana":"ほんがんじよっかいちべついんにのもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"大分県","address":"大分県宇佐市四日市1410-1","lat":33.531249,"lng":131.326067,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口4.2m","structure_material":"木造","registered":"2016.02.25(平成28.02.25)","register_no":"44-0219","desc":"境内正面山門前の参道入口を飾る門。一間一戸の建ちの高い高麗門で、屋根は切妻造桟瓦葺で軒は一軒繁垂木である。親柱は五平の角柱、控柱は角柱で、控柱上部に切妻造の小屋根を付す。中備には彫刻付の蟇股を置き、妻飾りは笈形付大瓶束で棟木を支持する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011026"},{"id":"00011016","register_sub_id":"101","register_pk":"208986","name":"本願寺四日市別院本堂","kana":"ほんがんじよっかいちべついんほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県宇佐市四日市1410-1","lat":33.531287,"lng":131.325183,"geo_status":"db","era":"安政6（1859）","year":1859,"year_source":"db","year_min":1859,"year_max":1859,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積1212㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"44-0209","desc":"境内中央に東面して建つ。本堂は桁行三〇メートルの規模を誇り九州最大の木造建築とされる。外陣は畳敷の大空間で、木太い軸組架構を見せる。内陣は彫刻や金箔、彩色で装飾され、来迎柱に須弥壇を構え、背後に後堂を設けるなど本格的な真宗本堂の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011016"},{"id":"00012263","register_sub_id":"101","register_pk":"353064","name":"妙壽寺経蔵","kana":"みょうじゅじきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"大分県","address":"大分県豊後高田市金谷町598-1","lat":33.557522,"lng":131.441317,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"土蔵造平屋建、瓦葺、建築面積51㎡、輪蔵付","structure_material":"土蔵造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"44-226","desc":"本堂南に東面して建つ。方三間、土蔵造、向拝一間、宝形造。外壁は柱や内法長押を形作り、軒まで塗込める。内部は磚敷で、天井は格天井に天井画を施し、中央に八角輪蔵を据える。正面両脇間に花頭窓を設け、丸桁に唐草の鏝絵を施し、特徴ある外観をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012263"},{"id":"00012266","register_sub_id":"101","register_pk":"353067","name":"妙壽寺山門","kana":"みょうじゅじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県豊後高田市金谷町598-1","lat":33.558149,"lng":131.441617,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造、瓦葺、間口3.5m、左右袖塀付","structure_material":"木造","registered":"2018.03.27(平成30.03.27)","register_no":"44-229","desc":"境内の東面を画する山門。間口三・五メートルの四脚門で、切妻造、本瓦葺。本柱は円柱、控柱は角柱で、中備蟇股で、両脇に三斗を組む。妻飾は大ぶりの板蟇股を置き、蟇股には波を彫る。中門より小ぶりながら、古式をよく留め、風格ある佇まいをみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012266"},{"id":"00012264","register_sub_id":"101","register_pk":"353065","name":"妙壽寺鐘楼","kana":"みょうじゅじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県豊後高田市金谷町598-1","lat":33.557749,"lng":131.441456,"geo_status":"db","era":"宝暦11年(1761）","year":1761,"year_source":"db","year_min":1761,"year_max":1761,"year_label":null,"structure":"木造、瓦葺、面積11㎡","structure_material":"木造","registered":"2018.03.27(平成30.03.27)","register_no":"44-227","desc":"本堂南東方に建つ。方一間、入母屋造、本瓦葺。切石基壇上に角柱を四方転びに立て、腰貫、頭貫で固める。組物は支輪付出組で、地紋彫の見切板で折上げた格天井を張る。中備は間口いっぱいに幅広の蟇股で、牡丹の彫刻を施し、独創的な意匠をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012264"},{"id":"00012265","register_sub_id":"101","register_pk":"353066","name":"妙壽寺中門","kana":"みょうじゅじちゅうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"大分県","address":"大分県豊後高田市金谷町598-1","lat":33.557993,"lng":131.441464,"geo_status":"db","era":"江戸末期／昭和前期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口4.5m、左右袖塀付","structure_material":"木造","registered":"2018.03.27(平成30.03.27)","register_no":"44-228","desc":"本堂の東方に建つ。間口四・五メートルの四脚門で、入母屋造、本瓦葺。本柱は円柱、控柱は角柱で虹梁形頭貫で固め、組物は出組で、蟇股に菊花を彫刻する。天井は鏡天井。規模が大きく、支輪には地紋彫を施し、獏・獅子・麒麟の木鼻を付け壮麗な意匠の中門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012265"},{"id":"00012262","register_sub_id":"101","register_pk":"353063","name":"妙壽寺本堂","kana":"みょうじゅじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県豊後高田市金谷町599","lat":33.557588,"lng":131.441107,"geo_status":"db","era":"明治35年頃／平成11年改修","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積764㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"44-225","desc":"境内奥に東面して建つ。桁行九間、梁間八間、向拝三間で後堂を付す。軒支柱上に枠肘木を組み、外側を出組にして巻斗、実肘木で丸桁を受ける凝った意匠をみせる。浄土真宗本堂の標準平面で、組物は出組で、外陣格天井を高く張る、規模壮大で優美な意匠の本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012262"},{"id":"00008390","register_sub_id":"101","register_pk":"134032","name":"五百禩神社石橋及び石垣","kana":"いおしじんじゃいしばしおよびいしがき","category":"宗教","subcategory":"土木構造物","type_guess":"塀・手水舎","type_guess_confidence":"low","period":"明治","pref":"宮崎県","address":"宮崎県日南市大字楠原字寺の脇1-1他","lat":31.62459814,"lng":131.34718802,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"石橋 石造桁橋、橋長4.1m、幅員4.2m、石垣 石造、延長43m","structure_material":"石橋 石造桁橋","registered":"2010.09.10(平成22.09.10)","register_no":"45 － 0070","desc":"石塀から東方に堀割石垣と石橋が設置される。石橋は中央に橋脚を設け、太鼓状に桁を架け、十本の石材を渡す。幅４．２ｍ、橋長４．１ｍで、両側に低い欄干を設置する。石材は地元の飫肥石。石垣は堀の土留で、切石間知積とし、高さ０．７ｍ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008390"},{"id":"00008389","register_sub_id":"101","register_pk":"134031","name":"五百禩神社石塀","kana":"いおしじんじゃいしべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"宮崎県","address":"宮崎県日南市大字楠原字寺の脇1-1他","lat":31.62453908,"lng":131.3469806,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"石造、延長64m","structure_material":"石造","registered":"2010.09.10(平成22.09.10)","register_no":"45 － 0069","desc":"拝殿の前方に設けられる。東西に延びる参道途中の石段沿いに２．９ｍ設けられ、最下段から北へ１２ｍ、南は２０ｍで、最南端で東に折れ曲がり、山裾を囲うように設置される。高さ１．５ｍで精緻な切石間知積とする。神殿域を厳然と画する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008389"},{"id":"00008388","register_sub_id":"101","register_pk":"134030","name":"五百禩神社神楽殿及び拝殿","kana":"いおしじんじゃかぐらでんおよびはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"宮崎県","address":"宮崎県日南市大字楠原字寺の脇1-1他","lat":31.62464759,"lng":131.34664557,"geo_status":"db","era":"明治9年／明治37年改修","year":1876,"year_source":"db","year_min":1876,"year_max":1876,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積49㎡、渡殿付","structure_material":"木造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"45 － 0068","desc":"本殿の前方に拝殿と神楽殿が続く。神楽殿は一間向拝付の入母屋造で、桁行三間梁間二間、周囲に縁をまわす。拝殿は神楽殿後方に突出する切妻造桁行三間の建物で、いずれも方柱で、板敷。拝殿背後には渡殿をさらに付設する。整備された礼拝空間を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008388"},{"id":"00008387","register_sub_id":"101","register_pk":"134029","name":"五百禩神社本殿","kana":"いおしじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"宮崎県","address":"宮崎県日南市大字楠原字寺の脇1-1他","lat":31.62467805,"lng":131.34650661,"geo_status":"db","era":"明治9年／明治37年改修","year":1876,"year_source":"db","year_min":1876,"year_max":1876,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積23㎡","structure_material":"木造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"45 － 0067","desc":"境内の西奥に位置し、東面して建つ。三間社流造、桟瓦葺。正側面に擬宝珠高欄付の縁をまわす。方柱で、直接に桁を受け、妻は豕叉首とする。内部は板敷で、後方に壇を設ける。建ちの高い外観になり、装飾を抑えた清冽な社殿である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008387"},{"id":"00001379","register_sub_id":"101","register_pk":"102369","name":"大御神社幣殿・拝殿","kana":"おおみじんじゃへいでん・はいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"宮崎県","address":"宮崎県日向市大字日知屋字伊勢ヶ浜1","lat":32.41101407,"lng":131.64938942,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積35㎡","structure_material":"木造平屋建","registered":"1999.10.14(平成11.10.14)","register_no":"45 － 0009","desc":"本殿と棟を平行に置いた３間×３間，切妻造平入の拝殿から本殿に向けて直交棟の切妻屋根を架けて幣殿に充て，拝殿寄りの幣殿左右に切妻造の神饌所と神具所を配す。それぞれの社殿機能を表す多彩な屋根構成と均整のとれたヴォリューム構成に見所がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001379"},{"id":"00001378","register_sub_id":"101","register_pk":"102368","name":"大御神社本殿","kana":"おおみじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"宮崎県","address":"宮崎県日向市大字日知屋字伊勢ヶ浜1","lat":32.41094755,"lng":131.64946952,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積25㎡","structure_material":"木造平屋建","registered":"1999.10.14(平成11.10.14)","register_no":"45 － 0008","desc":"「日向のお伊勢さま」として知られる神社の本殿。伊勢ヶ浜の日向灘を見下ろす崖上に海を背に，高千穂に正面を向けて建つ。棟持柱を持つ神明造りの三間社で，設計施工は地元の谷山武義。形式・規模等について県社寺課の指導を受けたと伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001378"},{"id":"00004090","register_sub_id":"101","register_pk":"105080","name":"願心寺山門","kana":"がんしんじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"大正","pref":"宮崎県","address":"宮崎県都城市庄内町12467","lat":31.77221007,"lng":131.02226917,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造、瓦葺、間口4.1m、左右袖塀付","structure_material":"木造","registered":"2004.03.02(平成16.03.02)","register_no":"45 － 0024","desc":"入母屋造，銅板葺の四脚門で，左右に築地塀形式の板壁をＬ字型に設ける。四隅の角柱は腰長押より下部を外拡がりとし，出組と蟇股をあげ，二軒繁垂木で前後に軒唐破風をつけた軒を受ける。全体に精緻な技巧を駆使した豪放な門で，寺院の正面景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004090"},{"id":"00004089","register_sub_id":"101","register_pk":"105079","name":"願心寺本堂","kana":"がんしんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"宮崎県","address":"宮崎県都城市庄内町12467","lat":31.77248659,"lng":131.02279781,"geo_status":"db","era":"明治39","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積674㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"45 － 0023","desc":"入母屋造，桟瓦葺，妻入で，彫刻欄間を備えた本格的な浄土真宗本堂。入母屋造で軒唐破風付の門風につくられた正面の向拝，ペディメントを付けた洋風上げ下げ窓など，要所には類例の少ない特異な造形がみられる。棟札から棟梁は鹿児島県川辺町の中村辰次郎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004089"},{"id":"00008085","register_sub_id":"101","register_pk":"128916","name":"宮崎神宮石柵","kana":"みやざきじんぐういしさく","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"宮崎県","address":"宮崎県宮崎市神宮2-485-1他","lat":31.93789117,"lng":131.42312612,"geo_status":"db","era":"明治40","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"コンクリート造、延長235m","structure_material":"コンクリート造","registered":"2010.01.15(平成22.01.15)","register_no":"45-0065","desc":"玉垣の東・西端から北に延び拝所や神殿域を囲み、神域背面の船塚古墳の石垣に至り、総延長２３５ｍに及ぶ。布石上に方形の柱を建て、７本おきに太い面取柱とし、鉄製の控えを付ける。上部を笠石を載せて固める。コンクリートによる人造石で造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008085"},{"id":"00008080","register_sub_id":"101","register_pk":"128911","name":"宮崎神宮御料屋","kana":"みやざきじんぐうごりょうや","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"宮崎県","address":"宮崎県宮崎市神宮2-485-1他","lat":31.9384041,"lng":131.42375311,"geo_status":"db","era":"明治40","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積47㎡、渡廊付","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"45-0060","desc":"幣殿の東方に、桁行五間単廊の渡廊で繋がる。桁行四間梁間三間、南北棟の切妻造銅板葺で、神饌所と同じ規模、形式になる。舟肘木で、妻は豕叉首組とし、軒は一軒疎垂木。平入の幣殿を中心に切妻を正面に見せる二棟を東西に配し、対称性の強い正面をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008080"},{"id":"00008079","register_sub_id":"101","register_pk":"128910","name":"宮崎神宮神饌所","kana":"みやざきじんぐうしんせんじょ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"宮崎県","address":"宮崎県宮崎市神宮2-485-1他","lat":31.93834148,"lng":131.42326908,"geo_status":"db","era":"明治40","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積47㎡、渡廊付","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"45-0059","desc":"幣殿の西方に位置し、単廊の渡廊で繋がる。桁行四間梁間三間、南北棟の切妻造銅板葺。基壇上に円柱を建て、地覆や貫、内法長押で固め、柱上舟肘木。妻面は板壁で、平側に連子窓や妻戸を装置する。内部は一室で、北面に奥行の浅い神棚などを設ける。神饌所の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008079"},{"id":"00008076","register_sub_id":"101","register_pk":"128907","name":"宮崎神宮神殿","kana":"みやざきじんぐうしんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"宮崎県","address":"宮崎県宮崎市神宮2-485-1他","lat":31.93836496,"lng":131.42351501,"geo_status":"db","era":"明治40","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積30㎡","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"45-0056","desc":"境内の後方、船塚古墳を背に南面して建つ。切妻造妻入銅板葺で、千木と堅魚木を付ける。桁行三間梁間三間で高く床を張り、周囲に組高欄付の榑縁をまわす。正面中央に幣軸を構え両開戸をたて、他は横板壁。軒の深い緩やかな屋根をもち、安定感のある外観になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008076"},{"id":"00008081","register_sub_id":"101","register_pk":"128912","name":"宮崎神宮透間垣","kana":"みやざきじんぐうすきまがき","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"low","period":"明治","pref":"宮崎県","address":"宮崎県宮崎市神宮2-485-1他","lat":31.93867743,"lng":131.42345369,"geo_status":"db","era":"明治40","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造、銅板葺、延長88m","structure_material":"木造","registered":"2010.01.15(平成22.01.15)","register_no":"45-0061","desc":"神饌所と御料屋の北面から、本殿を半八角形状に囲む。延長８８ｍ。基壇上に円柱を建て、地覆や腰長押、内法長押で固め、腰板壁で連子窓を開け、南寄りに両開板戸を設け、出入口とする。柱上部から腕木状の材を出し、板軒を支持。軽快な意匠で、丁寧に造られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008081"},{"id":"00008083","register_sub_id":"101","register_pk":"128914","name":"宮崎神宮正門","kana":"みやざきじんぐうせいもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"宮崎県","address":"宮崎県宮崎市神宮2-485-1他","lat":31.93784287,"lng":131.42361476,"geo_status":"db","era":"明治40","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造、銅板葺、間口5.5m","structure_material":"木造","registered":"2010.01.15(平成22.01.15)","register_no":"45-0063","desc":"拝所の南方、参道正面に位置する。間口５．５ｍと規模の大きい四脚門。切妻造銅板葺。本柱・控柱とも円柱で、冠木や貫で固め、控柱上には舟肘木を置く。一軒疎垂木とし、豕叉首組、中備に束を建てる。菊紋の大きな金具を飾る板戸両開をたてる。簡明で重厚な門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008083"},{"id":"00008084","register_sub_id":"101","register_pk":"128915","name":"宮崎神宮玉垣","kana":"みやざきじんぐうたまがき","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"low","period":"明治","pref":"宮崎県","address":"宮崎県宮崎市神宮2-485-1他","lat":31.93781813,"lng":131.42346632,"geo_status":"db","era":"明治40","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造、銅板葺、延長119m","structure_material":"木造","registered":"2010.01.15(平成22.01.15)","register_no":"45-0064","desc":"正門の左右から東西に延びる垣で、一度南に折れ、再び東西に続く。総延長１１９ｍ。基壇上に円柱を建て、地覆で固め、柱上に腕木状の材を出して板軒を支持。背面には控えを建て、柱間は木柵とする。屋根は猿頭型の銅板瓦棒葺とする。森厳たる雰囲気で神域を画する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008084"},{"id":"00008086","register_sub_id":"101","register_pk":"128917","name":"宮崎神宮徴古館","kana":"みやざきじんぐうちょうこかん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"明治","pref":"宮崎県","address":"宮崎県宮崎市神宮2-485-1他","lat":31.93745062,"lng":131.4242188,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造2階建、瓦葺、建築面積205㎡","structure_material":"木造2階建","registered":"2010.01.15(平成22.01.15)","register_no":"45-0066","desc":"神門の東南、木立の中に所在する。桁行１８ｍ梁間１１ｍの木造２階建。寄棟造妻入桟瓦葺で、西正面に切妻屋根を付け、玄関とする。外壁は全体を海鼠壁とし、隅と階境に柱型などを造り出し、鉄格子を嵌める上げ下げ窓を等間隔に配する。独特の意匠になる展示館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008086"},{"id":"00008082","register_sub_id":"101","register_pk":"128913","name":"宮崎神宮拝所","kana":"みやざきじんぐうはいしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"宮崎県","address":"宮崎県宮崎市神宮2-485-1他","lat":31.93807653,"lng":131.42356528,"geo_status":"db","era":"明治40","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積42㎡","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"45-0062","desc":"幣殿の南方、正門との中程に位置する。桁行三間梁間三間、切妻造銅板葺。礎石上に円柱を建て、内法貫で固め、舟肘木を置き、桁や梁を支持。小壁を板壁とし、一軒疎垂木。四方吹放ちで、石敷、化粧屋根裏とし、各梁間に豕叉首を組む。大規模で、開放的な拝所。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008082"},{"id":"00008077","register_sub_id":"101","register_pk":"128908","name":"宮崎神宮幣殿","kana":"みやざきじんぐうへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"宮崎県","address":"宮崎県宮崎市神宮2-485-1他","lat":31.93854435,"lng":131.42347587,"geo_status":"db","era":"明治40","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積141㎡","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"45-0057","desc":"本殿の南に位置する、東西棟の切妻造銅板葺。桁行七間梁間四間、正面に三間向拝を付け、四周に組高欄付榑縁を巡らす。円柱で、舟肘木を置き、一軒繁垂木。中央三間に双折両開板戸、両端二間に蔀を装置。妻は豕叉首で、棟木筋にも豕叉首を組む独特の構法を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008077"},{"id":"00008078","register_sub_id":"101","register_pk":"128909","name":"宮崎神宮渡殿","kana":"みやざきじんぐうわたりでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"明治","pref":"宮崎県","address":"宮崎県宮崎市神宮2-485-1他","lat":31.93845955,"lng":131.42349349,"geo_status":"db","era":"明治40","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積40㎡","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"45-0058","desc":"本殿と幣殿を繋ぐ、南北棟の建物。切妻造銅板葺で南は幣殿屋根に取り付く。桁行四間梁間一間で、高欄付の榑縁を東西に張る。円柱、舟肘木とし、一軒疎垂木。床拭板敷で、化粧屋根裏天井とし、豕叉首組を見せる。吹放ちであるが、腰に蔀を嵌め込むことができる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008078"},{"id":"00005688","register_sub_id":"101","register_pk":"106676","name":"霧島神宮社務所","kana":"きりしまじんぐうしゃむしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"鹿児島県","address":"鹿児島県霧島市霧島田口","lat":31.85789113,"lng":130.86973362,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積548㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"46 － 0024","desc":"南東を向いて建ち，正面中央に切妻造の玄関を突出し，北に座敷飾りを備えた応接室等，南には中廊下式で斎館や事務室等を配する。良材を用いた上質なつくりになる大規模和風建築で，複雑な平面に対応した屋根を巧妙に架け，落ち着いた社頭景観を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005688"},{"id":"00007154","register_sub_id":"101","register_pk":"108136","name":"新照寺石塀","kana":"しんしょうじいしべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県姶良市住吉字櫻木545","lat":31.7620026,"lng":130.595026,"geo_status":"db","era":"明治28","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"石造、延長58m","structure_material":"石造","registered":"2008.04.18(平成20.04.18)","register_no":"46 － 0071","desc":"境内地の南辺と西辺際に流れる水路に沿って築いた城郭風石積擁壁の上に、尺角状の長石を３段に積み、頂部に笠石を載せる。門柱同様に出隅部の笠石に反りをつけるなど凝ったつくりに特徴がある。石塀に嵌め込まれた銘板石から年代が判明。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007154"},{"id":"00007153","register_sub_id":"101","register_pk":"108135","name":"新照寺正門","kana":"しんしょうじせいもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"鹿児島県","address":"鹿児島県姶良市住吉字櫻木545","lat":31.76193625,"lng":130.59522524,"geo_status":"db","era":"明治28","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"石造、間口3.1m、袖塀付","structure_material":"石造","registered":"2008.04.18(平成20.04.18)","register_no":"46 － 0070","desc":"本堂正面の南方に位置し、前面道路からの斜路を登りきった地点に建つ。間口３．１ｍ、門柱高３．４ｍで、門柱は几帳面を施した石柱とし、頂部に反りをつけた笠石を載せる。左右には６段積に笠石を載せた袖塀が取り付き、石造の本堂に対応した門構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007153"},{"id":"00007155","register_sub_id":"101","register_pk":"108137","name":"新照寺通用門","kana":"しんしょうじつうようもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"鹿児島県","address":"鹿児島県姶良市住吉字櫻木545","lat":31.76214519,"lng":130.59502696,"geo_status":"db","era":"明治28","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"石造、間口1.1m","structure_material":"石造","registered":"2008.04.18(平成20.04.18)","register_no":"46 － 0072","desc":"本堂外陣の西方、石塀北端部に位置し、西側道路から登る９段の石階段の上に建つ。間口１．１ｍ、門柱高２．０ｍの石造門で、１本石の長石を門柱とし、門柱間に屋根型の楣石を載せる。楣石の上面につけた反りが、正門及び石塀と同時期の築造を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007155"},{"id":"00007152","register_sub_id":"101","register_pk":"108134","name":"新照寺本堂","kana":"しんしょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県姶良市住吉字櫻木545","lat":31.76218961,"lng":130.59518169,"geo_status":"db","era":"明治25","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"石造平屋建、瓦葺、建築面積290㎡","structure_material":"石造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"46 － 0069","desc":"正面梁間１６ｍ桁行１８ｍ、寄棟造妻入桟瓦葺の石造本堂で、正面屋根を切り上げて前面に葺き降ろし向拝とする。外周の石造壁は側・背面に各２ヶ所の控壁を設け、４隅は算木状に突きだした隅石風の意匠を採る。棟札により上棟年代と石工棟梁及び大工棟梁が判明。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007152"},{"id":"00007157","register_sub_id":"101","register_pk":"108139","name":"瀬留カトリック教会司祭館","kana":"せどめかとりっくきょうかいしさいかん","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県大島郡龍郷町大字瀬留字中郷原271-1","lat":28.4239699,"lng":129.59150311,"geo_status":"db","era":"明治41頃／昭和62改修","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積114㎡","structure_material":"木造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"46 － 0074","desc":"教会聖堂の東に位置し、東西棟で建つ。桁行１２ｍ梁間６．０ｍ規模、寄棟造鉄板葺の木造２階建で、北側に平屋建の附属屋を突出させる。外部は下見板張に仕上げる。改造はあるが、教会聖堂とともに奄美大島におけるカトリック布教の足跡の一端を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007157"},{"id":"00007156","register_sub_id":"101","register_pk":"108138","name":"瀬留カトリック教会聖堂","kana":"せどめかとりっくきょうかいせいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県大島郡龍郷町大字瀬留字中郷原271-1","lat":28.42384221,"lng":129.59137693,"geo_status":"db","era":"明治41／昭和24・昭和62改修","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積221㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"46 － 0073","desc":"桁行２０ｍ梁間１１ｍ規模、北側を寄棟造、南側を入母屋造とし、南面に切妻造の玄関を突出させた教会堂で、外部は下見板張とする。正面外観は大きく改造されているが、内部は３廊式で、身廊部を高くし側廊ともに平天井を張り、創建時の面影をよく留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007156"},{"id":"00007942","register_sub_id":"101","register_pk":"128546","name":"都萬神社拝殿","kana":"つまじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"鹿児島県","address":"鹿児島県曽於郡大崎町假宿字西迫1589","lat":31.4266994,"lng":131.00963421,"geo_status":"db","era":"大正5／平成9改修","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積66㎡","structure_material":"木造平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"46-0087","desc":"本殿の前方に南面して建つ。桁行四間梁間三間、入母屋造妻入、向拝一間、桟瓦葺。本殿との間に、桁行三間梁間一間の回廊を付ける。方柱で、木鼻付平三斗組とし、中備に蟇股を飾る。一軒疎垂木。回廊も同じ仕様。装飾的な本殿と対照的に簡明な意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007942"},{"id":"00007941","register_sub_id":"101","register_pk":"128545","name":"都萬神社本殿","kana":"つまじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"鹿児島県","address":"鹿児島県曽於郡大崎町假宿字西迫1589","lat":31.42679918,"lng":131.00956124,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積53㎡","structure_material":"木造平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"46-0086","desc":"小高い丘陵地に占める境内地の北寄りに、南面して建つ。桁行正面三間背面四間、梁間三間、入母屋造、向拝一間、桟瓦葺の社殿。組物は平三斗上に絵様肘木を置き、巻斗５個を並べ、前方へ三段に木鼻を出す特殊な形。中備の蟇股には十二支のレリーフを飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007941"},{"id":"00007943","register_sub_id":"101","register_pk":"128547","name":"都萬神社末社伊勢宮","kana":"つまじんじゃまっしゃいせみや","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"鹿児島県","address":"鹿児島県曽於郡大崎町假宿字西迫1589","lat":31.42682598,"lng":131.00943317,"geo_status":"db","era":"大正5／平成17頃改修","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積1.2㎡","structure_material":"木造平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"46-0088","desc":"本殿の西方に南面して建つ社殿。桁行一間梁間一間、入母屋造、向拝一間、銅板葺。円柱で三斗組とし、中備に蟇股を配す。軒は二軒繁垂木。正面に格子戸をたて、側・背面は横板壁とする。向拝の蟇股や組物はやや大振りで、蟇股に夫婦岩を彫る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007943"},{"id":"00007944","register_sub_id":"101","register_pk":"128548","name":"都萬神社末社稲荷神社","kana":"つまじんじゃまっしゃいなりじんじゃ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"鹿児島県","address":"鹿児島県曽於郡大崎町假宿字西迫1589","lat":31.42681109,"lng":131.00940189,"geo_status":"db","era":"大正5／平成17改修","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積1.1㎡","structure_material":"木造平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"46-0089","desc":"末社伊勢宮の西に南面して建つ。小規模な一間社。流造屋根で銅板葺。円柱を切目長押や内法長押で固め、頭貫を通す。木鼻には雲紋風に絵様を施す。二軒繁垂木。正面中備の蟇股は本殿などと同様の形になり、大正再建の経緯が陰刻される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007944"},{"id":"00007945","register_sub_id":"101","register_pk":"128549","name":"都萬神社末社五林大明神社","kana":"つまじんじゃまっしゃごりんだいみょうじんじゃ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"鹿児島県","address":"鹿児島県曽於郡大崎町假宿字西迫1589","lat":31.42689597,"lng":131.00959995,"geo_status":"db","era":"大正5／平成17頃改修","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積0.53㎡","structure_material":"木造平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"46-0090","desc":"本殿の東に南面して建つ。末社の中で最も小規模な社殿。一間社流見世棚造、銅板葺。方柱で三斗組とし、二軒繁垂木。向拝身舎間には海老虹梁を架けて、固める。向拝は方柱で、柱上に木鼻付平三斗を置く。水引虹梁は二段に折り上げ、中央に蟇股を飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007945"},{"id":"00007946","register_sub_id":"101","register_pk":"128550","name":"都萬神社末社山王神社","kana":"つまじんじゃまっしゃさんおうじんじゃ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"鹿児島県","address":"鹿児島県曽於郡大崎町假宿字西迫1589","lat":31.42691384,"lng":131.00962378,"geo_status":"db","era":"大正5／平成17頃改修","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積1.2㎡","structure_material":"木造平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"46-0091","desc":"末社五林大明神社の東に、南面して建つ小規模な社殿。桁行一間梁間一間、入母屋造、向拝一間、銅板葺。円柱で、三斗組とし、中備に蟇股を飾る。二軒繁垂木。向拝には皿斗付大斗を用い、平三斗とする。本殿と同時期の社殿群が、伝統的な境内景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007946"},{"id":"00005776","register_sub_id":"101","register_pk":"106764","name":"南洲神社電燈","kana":"なんしゅうじんじゃでんとう","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"鹿児島県","address":"鹿児島県鹿児島市上竜尾町2-1","lat":31.606264,"lng":130.559601,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"鉄製2基、高さ4.4m","structure_material":"鉄製2基","registered":"2006.10.18(平成18.10.18)","register_no":"46 － 0033","desc":"南洲神社拝殿の参道，石段を登った両脇に一対立つ。高さ４．４ｍの鋳鉄製で，柱脚は六角形の断面，柱頭は六方に開いた花弁状で飾り，各接合部には繰形などの装飾を付ける。近代日本の礎となった旧集成館が製造した数少ない遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005776"},{"id":"00016762","register_sub_id":"101","register_pk":"579246","name":"島根殿アガリユーヌウトゥーシ","kana":"しまにどぅんあがりゆーぬうとぅーし","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"沖縄県","address":"沖縄県中頭郡北中城村字熱田東原68-1","lat":26.296201,"lng":127.80777,"geo_status":"db","era":"昭和15年頃","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"鉄筋コンクリート造平屋建、面積0.6㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"47 - 0095","desc":"境内の東側に位置し、東方のニライカナイに向かって豊穣を祈願する拝所。高い基壇上に建つ方一間、鉄筋コンクリート造切妻造平入、モルタル洗出仕上。正面中央に透鉄扉を開き、内部の祭壇に香炉を配する。小規模ながら重厚な姿で、独特な境内景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016762"},{"id":"00016763","register_sub_id":"101","register_pk":"579247","name":"島根殿鳥居","kana":"しまにどぅんとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"昭和前","pref":"沖縄県","address":"沖縄県中頭郡北中城村字熱田東原68-1","lat":26.296144,"lng":127.807737,"geo_status":"db","era":"昭和15年","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"鉄筋コンクリート造、間口2.7m、高さ3.3m","structure_material":"鉄筋コンクリート造","registered":"2026.07.09(令和8.07.09)","register_no":"47 - 0096","desc":"本殿と拝殿の軸線上に建つ神明鳥居。全高三・三メートル、柱間二・七メートル、鉄筋コンクリート造、モルタル洗出仕上とする。一対の円柱を立てて、頂部に円柱の笠木形を渡し、貫の楔や額束も設けず、全体に簡素なつくり。境内の歴史的な景観を形成する鳥居。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016763"},{"id":"00016761","register_sub_id":"101","register_pk":"579245","name":"島根殿拝殿","kana":"しまにどぅんはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"沖縄県","address":"沖縄県中頭郡北中城村字熱田東原68-1","lat":26.296169,"lng":127.807582,"geo_status":"db","era":"昭和15年","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積12㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"47 - 0094","desc":"本殿の前方に東面して建つ拝殿。木造平屋建入母屋造、琉球赤瓦葺。方三間で角柱を立て、組物は舟肘木。四方とも中央一間を開放とし、両脇間は腰壁を設ける。内部はタイル貼の土間で棹縁天井を張る。滴水瓦で軒先を飾り、地域の特色ある境内景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016761"},{"id":"00016760","register_sub_id":"101","register_pk":"579244","name":"島根殿本殿","kana":"しまにどぅんほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"沖縄県","address":"沖縄県中頭郡北中城村字熱田東原68-1","lat":26.296159,"lng":127.80762,"geo_status":"db","era":"昭和15年","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積1.9㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"47 - 0093","desc":"集落中心部に位置する旧御嶽を神社化した本殿。鉄筋コンクリート造一間社流造で、屋根に鳥衾付鬼板を載せる。垂木を疎らに配って簡略化した形態とするが、組物や絵様まで精巧につくる。昭和戦前に沖縄で進展した、御嶽の神社化を示す貴重な耐火建築の本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016760"},{"id":"00010242","register_sub_id":"101","register_pk":"199016","name":"飯田家住宅座敷棟","kana":"いいだけじゅうたくざしきとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"北海道","address":"北海道沙流郡日高町富川南1-401-50","lat":42.518896,"lng":142.028774,"geo_status":"db","era":"明治44年／昭和26年移築","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積56㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"01-0142","desc":"皇太子（後の大正天皇）行啓時の宿所として旧門別町で建てられた建物の座敷二室と東廊下の主体部を移築し、周囲に増築した。軸部にヒノキの良材をふんだんに使い、折上格天井、トコ、付書院、建具、錺金具などの内部造作は善美を尽くした気品ある意匠になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010242"},{"id":"00010715","register_sub_id":"101","register_pk":"201550","name":"飯田家住宅主屋","kana":"いいだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"北海道","address":"北海道沙流郡日高町門別本町92他","lat":42.47584,"lng":142.075618,"geo_status":"db","era":"明治後期／昭和40改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、鉄板葺、建築面積169㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"01 ‐ 0146","desc":"太平洋に面する海辺に建つ住宅。東面して玄関を構え、西寄りに応接用の洋間を持ち、矩折れの廊下を介して北西側に二室の座敷を配する。一五畳主室は棹縁天井を高く張り、大振りの床を構える座敷飾を備え、上下窓を並べる。和洋の意匠を取り混ぜた上質な住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010715"},{"id":"00010092","register_sub_id":"101","register_pk":"197925","name":"遠藤家住宅表門","kana":"えんどうけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"北海道","address":"北海道札幌市中央区南6条西5-18","lat":43.05310573,"lng":141.35116024,"geo_status":"db","era":"大正8頃","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造、瓦葺、間口2.5m、左右袖塀及び潜戸付","structure_material":"木造","registered":"2014.10.07(平成26.10.07)","register_no":"01 － 0140","desc":"敷地南辺、主屋玄関の斜め前方に構える、間口二・五メートルの一間薬医門である。屋根面と化粧垂木ともに緩く起りをつけた切妻造で、桟瓦葺とする。左右袖塀は潜戸をもち、石塀に接続する。規模と木割の大きな風格ある表門で、屋敷の表構えを構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010092"},{"id":"00010091","register_sub_id":"101","register_pk":"197924","name":"遠藤家住宅北石蔵","kana":"えんどうけじゅうたくきたいしくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"北海道","address":"北海道札幌市中央区南6条西5-18他","lat":43.053247,"lng":141.351044,"geo_status":"db","era":"大正8頃","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"石造平屋建、鉄板葺、建築面積29㎡","structure_material":"石造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"01 － 0139","desc":"敷地東辺北寄りに建つ、札幌軟石を布積とした平入の蔵で、南石蔵と同形式とするが、桁行が九・一メートルと長い。軒先に鉢巻を廻らし軒蛇腹を付す。南北妻面の窓は隅部を丸く縁取り、鉄格子を入れる。石塀と一体的に建てられた堅牢な蔵で敷地景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010091"},{"id":"00010089","register_sub_id":"101","register_pk":"197922","name":"遠藤家住宅蔵","kana":"えんどうけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"北海道","address":"北海道札幌市中央区南6条西5-18他","lat":43.053247,"lng":141.351044,"geo_status":"db","era":"大正8頃","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"煉瓦造2階建、瓦葺、建築面積54㎡","structure_material":"煉瓦造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"01 － 0137","desc":"主屋の北西に接続する二階建の煉瓦蔵。焼過煉瓦のイギリス積で、両妻をブロークンペディメントとして庇付窓をあけ、コーニスに歯飾りを飾る。小屋組はキングポストトラスで、内部階段も洋風意匠とする。煉瓦造の主屋北壁とともに重厚な街路景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010089"},{"id":"00010088","register_sub_id":"101","register_pk":"197921","name":"遠藤家住宅主屋","kana":"えんどうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"北海道","address":"北海道札幌市中央区南6条西5-18他","lat":43.053247,"lng":141.351044,"geo_status":"db","era":"大正8頃／昭和10・昭和32・平成10改修","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造及びコンクリート造平屋建、瓦葺、建築面積671㎡、煙突付","structure_material":"木造及びコンクリート造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"01 － 0136","desc":"繁華街すすきのの一画に建つ、もと材木商の居宅。南正面に入母屋造の玄関を構え、西に内装洋風の応接室を配し、さらに六間取系の座敷部や離れ座敷を雁行させる。北面に日常居室部を連ね、煉瓦造の北壁は外塀を兼ねる。洗練された意匠を持つ上質な近代和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010088"},{"id":"00010093","register_sub_id":"101","register_pk":"197926","name":"遠藤家住宅塀","kana":"えんどうけじゅうたくへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"北海道","address":"北海道札幌市中央区南6条西5-18","lat":43.05329612,"lng":141.3508965,"geo_status":"db","era":"大正8頃","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"石造及び煉瓦造、総延長161m、門付","structure_material":"石造及び煉瓦造","registered":"2014.10.07(平成26.10.07)","register_no":"01 － 0141","desc":"敷地を囲む塀。東、南、西の三面は札幌軟石積とし、瘤出し仕上げで見付高さの異なる布石を交互に積む。北面は煉瓦造で、主屋の北壁を取込み、東寄りの一対の門柱と東面両隅に立てた柱には、幾何学意匠の柱頭を飾る。繁華街に風格ある景観を形成する塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010093"},{"id":"00010090","register_sub_id":"101","register_pk":"197923","name":"遠藤家住宅南石蔵","kana":"えんどうけじゅうたくみなみいしくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"北海道","address":"北海道札幌市中央区南6条西5-18他","lat":43.053247,"lng":141.351044,"geo_status":"db","era":"大正8頃","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"石造平屋建、鉄板葺、建築面積18㎡、地下室付","structure_material":"石造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"01 － 0138","desc":"敷地東辺南寄りに建つ、札幌軟石を布積とした平入の蔵で、東面の石塀を外壁とし、両妻に窓を穿つ。石塀内側に設けた石製持送で垂木掛を支持し、片流れの屋根をかける。南側にはムロに使用したコンクリート造の地下室が附属する。敷地内の景観を引き締める蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010090"},{"id":"00008232","register_sub_id":"101","register_pk":"133874","name":"旧青山家別邸板塀","kana":"きゅうあおやまけべっていいたべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"北海道","address":"北海道小樽市祝津3-63","lat":43.23188739,"lng":141.00866222,"geo_status":"db","era":"大正12年","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造、瓦葺一部鉄板葺、総延長73m","structure_material":"木造","registered":"2010.09.10(平成22.09.10)","register_no":"01 － 0110","desc":"敷地東面に建ち、境界から２ｍ下がった門柱へ南北両塀ともに折れ曲がり、北はさらに主屋へ延びる。総延長７３ｍ。二段の布基礎に土台をのせ、方柱を建て、壁は下見板張とする。上部に腕木を出し、疎垂木を配り、桟瓦を葺く。静閑な佇まいの屋敷構えを構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008232"},{"id":"00008230","register_sub_id":"101","register_pk":"133872","name":"旧青山家別邸主屋","kana":"きゅうあおやまけべっていしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"北海道","address":"北海道小樽市祝津3-63","lat":43.23180219,"lng":141.00828185,"geo_status":"db","era":"大正12年","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積450㎡","structure_material":"木造平屋一部2階建","registered":"2010.09.10(平成22.09.10)","register_no":"01 － 0108","desc":"敷地の北東寄りに建つ東西棟の入母屋造桟瓦葺、木造平屋建で、東北に２階建の離れを付設する。南正面の東と西に主玄関と脇玄関を対称に配置し、堂々とした正面とする。内部は春慶塗や銘木を用い、和・洋の意匠が部屋毎に違えて見られるなど、贅を凝らしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008230"},{"id":"00008231","register_sub_id":"101","register_pk":"133873","name":"旧青山家別邸文庫蔵","kana":"きゅうあおやまけべっていぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"北海道","address":"北海道小樽市祝津3-63","lat":43.23157894,"lng":141.00840193,"geo_status":"db","era":"大正12年","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積76㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"01 － 0109","desc":"主屋の南側に建つ。桁行１１ｍ梁間５．４ｍの土蔵造２階建で東西棟の切妻造桟瓦葺。北側に出格子を付け、下見板張、上部漆喰仕上げの下屋を付設する。黒漆喰仕上げで、東西妻の腰をモルタル洗出し仕上げとする。主屋とともに鰊漁で栄えた住宅のよすがを示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008231"},{"id":"00013343","register_sub_id":"101","register_pk":"368431","name":"旧五十嵐家住宅事務所兼主屋","kana":"きゅういがらしけじゅうたくじむしょけんおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"北海道","address":"北海道釧路市富士見二丁目65-22","lat":42.97666944,"lng":144.38995,"geo_status":"db","era":"昭和25年頃／平成13年改修","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造2階建、金属板葺、建築面積120㎡","structure_material":"木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"01 － 0160","desc":"釧路市内の住宅地に東面して建つ、木造二階建、切妻造金属板葺。玄関脇の事務所は防寒対策のため二重窓とし、西側に機能的な造付の設備を備えた台所を家の中央に配すなど、当地域の住宅では先駆的な試みも見られる。戦後間もない寒冷地対応住宅の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013343"},{"id":"00009570","register_sub_id":"101","register_pk":"194566","name":"旧岡田家住宅蔵","kana":"きゅうおかだけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"北海道","address":"北海道旭川市5条通16-1099他","lat":43.76600461,"lng":142.37376703,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造3階地下1階建、建築面積33㎡","structure_material":"鉄筋コンクリート造3階地下1階建","registered":"2013.06.21(平成25.06.21)","register_no":"01 － 0133","desc":"主屋南端に接続する鉄筋コンクリート造、陸屋根の什器蔵。外壁は下半が横目地入、上半が平滑なモルタル塗で二階建に見せ、内部は三層の木造床を張る。一階東側を区画して廊下とする。北面入口は両開鉄扉と木製引戸とし、各階西面窓の窓間のパネルが目をひく。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009570"}];
